(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-sigmoid-loss-for-language-image-pre-2023"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-1\">一 · 开场：一条检索请求如何在旧栈里被拖慢</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-2\">二 · 旧方案的机制：全局归一化如何把批变成同步点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-3\">三 · 代价账本：延迟、吞吐、显存与带宽的四笔账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-4\">四 · 为什么非改不可：服务侧的三个硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-5\">五 · 旧方案的负样本与温度：两个被继承的复杂度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-6\">六 · 落到工程判断：这条路径在 Blackwell 栈上的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-7\">七 · 请求形态：检索、零样本分类与嵌入批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-8\">八 · 输入长度分布：文本侧的长尾与图像侧的固定成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-9\">九 · 并发、批大小与 SLO：平方项如何反过来限制负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-10\">十 · 长尾：候选规模、冷启动与负对噪声</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-11\">十一 · 负载塑造方案，方案限制负载：双向回路与可核查口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-12\">十二 · 与 Blackwell 部署的接口：哪些结论可直接用，哪些必须实测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-13\">十三 · 相似度矩阵的逐元素算子形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-14\">十四 · 双塔 GEMM 与 tcgen05 的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-15\">十五 · 数据类型选择：FP16/BF16/FP8/NVFP4</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-16\">十六 · 累加精度与误差传播</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-17\">十七 · Blackwell 特性对损失归约的约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-18\">十八 · 从训练算子到推理服务的精度契约</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-19\">十九 · 显存账本的三层结构与可复算预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-20\">二十 · 相似度矩阵的平方项：批上限的硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-21\">二十一 · 带宽瓶颈的定位：HBM3e 与 KV 的读写比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-22\">二十二 · 分页、压缩、复用与卸载的组合策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-23\">二十三 · 精度与容量的联动：NVFP4/FP8 下的账本重算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-24\">二十四 · 批内相似度矩阵的显存账本与平方项边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-25\">二十五 · 从训练批到服务批：可分解损失如何改写调度约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-26\">二十六 · 连续批处理与 chunked prefill：把平方项摊到时间轴上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-27\">二十七 · 优先级与抢占：尾延迟的两种压缩手段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-28\">二十八 · 分离式预填/解码在双塔检索中的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-29\">二十九 · 批构成与负对噪声：调度器必须监控的隐性成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-30\">三十 · 批大小平方项如何反过来约束调度：从本地批上限到检索服务的尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-31\">三十一 · 从全局归一化到本地可分解：通信需求的结构性变化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-32\">三十二 · TP/EP/PP/DP 四种切分在双塔上的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-33\">三十三 · NVLink 5 与 NVSwitch：域内带宽的可用窗口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-34\">三十四 · All-to-All 与 All-Reduce 的代价分野</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-35\">三十五 · NIXL 传输：把嵌入搬运从计算路径上摘出来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-36\">三十六 · 通信何时成为瓶颈：三个可观测的信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-37\">三十七 · 通信何时退居次席：sigmoid 分解对并行切分的边界影响</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-38\">三十八 · 精度塌陷：从嵌入范数到排序翻转的链路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-39\">三十九 · OOM：平方项与分片边界的错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-40\">四十 · 批抖动：负对构成变化引发的损失不稳</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-41\">四十一 · 尾延迟：双塔独立前向的慢侧拖累</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-42\">四十二 · 静默降级：低精度路径与超参补偿的陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-43\">四十三 · 监控分层与回滚决策的工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-44\">四十四 · 批构成漂移与精度塌陷的定位路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-45\">四十五 · 口径先于数字：这篇论文能提供什么、不能提供什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-46\">四十六 · 相似度矩阵是唯一贯穿训练与推理的代价项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-47\">四十七 · 硬件档位与指标：论文未给的，必须自己定义测量口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-48\">四十八 · 哪些提升不可比：四类常见的口径错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-49\">四十九 · 双塔拆分带来的测量口径分裂</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-50\">五十 · 把论文结论落成可执行的容量判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-51\">五十一 · 口径边界：sigmoid 双塔在推理侧的不可比项与容量红线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-52\">五十二 · 从训练目标迁到推理服务：可迁移的是分解性，不是损失本身</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-53\">五十三 · 迁到非双塔架构：交叉编码器与生成式多模态要重做</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-54\">五十四 · 迁到低精度与 Blackwell 数值栈：没有现成数据，必须自己标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-55\">五十五 · 批构成与负对噪声：推理侧没有负对，但有候选集偏差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-56\">五十六 · 规模上限与不适用清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-57\">五十七 · 迁移边界：sigmoid 双塔方案在哪些系统上会失效</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:528px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 527.6 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"445.6\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">图像与文本分别经各自编码器前向，得到单模态嵌入表示。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"445.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">嵌入经投影头映射到共享维度并做 L2 归一化，形成可比相似度空间。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"445.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">在本地批内计算图文相似度矩阵，规模为批大小乘批大小。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"445.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对矩阵逐元素施加 sigmoid 二分类损失，正对标签为 1、负对为 …</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"445.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">损失在批内对全部图文对求和并归一化后反向传播，更新双塔参数。</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"445.6\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">推理阶段仅需双塔前向与相似度计算，用于图文检索与零样本分类。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-1\">一 · 开场：一条检索请求如何在旧栈里被拖慢</h3>\n<p>设想一个在线商品图文检索服务：用户上传一张照片，网关把请求分发给多模态检索后端，后端需要在毫秒级从千万级商品库中召回候选，再交给下游排序。前端只看到“上传—返回”两跳，但后端的第一跳决定了整条链路的下限。在这类服务里，图文双塔是主流结构：图像编码器出图嵌入，文本编码器出文本嵌入，两者投影到共享空间并做 L2 归一化，最后用点积排序。真正卡住这条链路的，往往不是编码器本身，而是旧方案在“如何构造可比对的批”上的工程假设——softmax 对比损失训练出的双塔，其嵌入空间的判别力与训练时的全局批构成强耦合，服务侧不得不为“批”付出额外代价。</p>\n<p>旧栈的典型形态是：训练阶段用 softmax 对比损失，把批内所有图文相似度放进一个全局归一化的 softmax 里，正对为对角元素，负对为非对角元素，温度参数调节分布锐度。为了让负样本足够“硬”，工程上被迫把全局批推到极大，跨设备做 all-gather 收集 logits，再算 softmax 与梯度。这条路径在推理侧留下三个后遗症：第一，嵌入空间的尺度与温度绑定，服务侧做点积排序时必须复现训练时的温度与归一化约定，否则排序质量漂移；第二，负对来自批内非对角元素，批构成一变，嵌入的判别边界就变，检索召回率对请求批的组成敏感；第三，为了维持训练时的批规模假设，服务侧倾向把请求攒成大批判处理，抬高了排队延迟与显存峰值。这就是“非改不可”的现场：不是模型不够大，而是目标函数把批变成了一个必须被伺候的全局对象。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-2\">二 · 旧方案的机制：全局归一化如何把批变成同步点</h3>\n<p>softmax 对比损失的机制可以写成：对批内第 i 个图像嵌入与第 j 个文本嵌入的相似度 s_ij，正对概率为 exp(s_ii/τ) 除以该行所有 exp(s_ij/τ) 之和，损失为负对数似然。关键在于分母跨越了整个批，因此每个样本的梯度都依赖批内其他所有样本的 logits。在多卡训练里，这意味着每步都要把各卡的相似度矩阵拼成全局矩阵，做一次跨设备的归约与再分发。通信量与批大小平方成正比，且是每步的硬同步点：任何一张卡慢下来，整批都等。</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\text{softmax}}=-\\frac{1}{N}\\sum_{i=1}^{N}\\log\\frac{\\exp(s_{ii}/\\tau)}{\\sum_{j=1}^{N}\\exp(s_{ij}/\\tau)}$$</div>\n<p>这条公式的工程含义是：批不是数据加载的副产品，而是目标函数的一部分。为了凑出足够多的负对，全局批被推到数千甚至更大，跨设备 all-gather 的 logits 矩阵在显存里驻留，峰值显存随批平方增长。对推理侧而言，这种耦合表现为一种隐式契约——服务必须按训练时的批统计来组织请求，否则嵌入的判别力下降。一个具体例子：某检索服务把在线请求按 32 条一批攒批，但训练时全局批是 4096，负对密度差了两位数量级，导致同一张图在不同批组成下召回的 top-k 排序不稳定，运维只能靠扩大攒批窗口来“稳”，延迟随之上升。这就是旧方案的核心痛点：目标函数要求全局同步，而服务侧要的是可分解、可独立处理的本地批。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-3\">三 · 代价账本：延迟、吞吐、显存与带宽的四笔账</h3>\n<p>把旧方案的代价拆成四笔账，能看清为什么改目标是工程问题而非学术趣味。延迟账：跨设备 all-gather 是每步的同步屏障，训练侧的步时被最慢卡支配；推理侧则表现为攒批窗口——为了凑出“像训练那样”的批，请求在队列里等待，P99 延迟被窗口长度直接抬高。吞吐账：全局 softmax 要求每步处理完整批，批规模受显存上限约束，吞吐无法通过缩小批来线性扩展；缩小批又会削弱负对密度，形成吞吐与质量的拉扯。显存账：相似度矩阵规模为批大小平方，N×N 的 logits 在反向传播时需要保留中间量，峰值显存随 N 二次增长；在双塔结构下，图像与文本编码器的激活再加上这块矩阵，构成部署时的容量瓶颈。带宽账：all-gather 的通信量随批平方增长，跨节点时走 NVLink 或网络，通信时间与计算时间争抢同一份预算。</p>\n<table class=\"mini\"><thead><tr><th>代价维度</th><th>旧方案（softmax 对比）</th><th>工程表现</th></tr></thead><tbody><tr><td>延迟</td><td>每步跨设备同步屏障；推理侧攒批窗口</td><td>P99 随窗口长度上升，慢卡拖整批</td></tr><tr><td>吞吐</td><td>批规模受显存与同步约束</td><td>缩小批削弱负对密度，吞吐与质量拉扯</td></tr><tr><td>显存</td><td>N×N logits 及反向中间量</td><td>峰值随批平方增长，双塔激活叠加</td></tr><tr><td>带宽</td><td>all-gather 通信量随批平方增长</td><td>通信与计算争抢预算，跨节点更明显</td></tr></tbody></table>\n<p>一个具体机制层面的例子：在 8 卡节点上做全局批 4096 的对比训练，每卡本地批 512，相似度矩阵在卡内是 512×512，但全局归一化需要把 8 份矩阵拼成 4096×4096 的视图做归约。反向时每张卡都要拿到全局分母的梯度，通信量与 4096 平方同阶。若把全局批降到 1024，通信量降一个数量级，但负对数量随之减少，softmax 的判别力下降，检索指标退化——这正是论文要回答的问题：能否用逐对独立的 sigmoid 损失，在较小批下拿到可比或更好的检索性能，同时把同步与显存代价降下来。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-4\">四 · 为什么非改不可：服务侧的三个硬约束</h3>\n<p>第一个硬约束是批构造的灵活性。在线检索的请求到达是泊松式的，攒批窗口越长，延迟越高；窗口越短，批越小，softmax 训练出的嵌入在小组批下判别力不稳。服务侧需要的是“每个图文对独立判定”的目标，这样本地批可以按显存与延迟预算自由切分，而不必为了负对密度去凑全局批。第二个硬约束是跨设备同步的预算。分离式预填/解码、多副本扩缩容这些服务形态要求各副本能独立处理请求，而 softmax 的全局归一化把副本绑成一个同步域，扩缩容时同步拓扑变化会引入抖动。第三个硬约束是显存峰值的可预测性。N×N 矩阵的二次增长让容量规划变成猜谜：批大一档，显存翻几倍，OOM 风险与批调度策略强耦合。</p>\n<p>论文的切入点是把这个全局对象拆掉：把批内每个图文对视为独立二分类，正对标签为 1、负对标签为 0，逐元素算 sigmoid 概率，损失对批内全部对求和后归一化。公式如下，其中 y_ij 为匹配标签，s_ij 为相似度。</p>\n<div class=\"formula\">$$\\mathcal{L}=-\\frac{1}{N}\\sum_{i=1}^{N}\\sum_{j=1}^{N}\\left[y_{ij}\\log\\sigma(s_{ij})+(1-y_{ij})\\log(1-\\sigma(s_{ij}))\\right]$$</div>\n<p>这条公式的关键性质是“可分解”：每个 (i,j) 对的损失只依赖该对的相似度，不依赖批内其他样本的归一化分母。因此梯度可以在本地批内闭合，无需跨设备对 logits 做全局归约。工程上这意味着批从“目标函数的一部分”退回“数据加载的单位”，服务侧可以按延迟预算切小批，训练侧可以用梯度累积模拟大批而不引入同步屏障。一个具体例子：把在线检索的攒批窗口从固定 64 条改为按 8 条一批、多副本并行处理，每副本独立算嵌入与点积排序，召回质量不再依赖批组成，P99 延迟由窗口长度决定变为由单批前向时间决定。代价转移到了另一处：相似度矩阵仍是批大小平方，本地批上限与分片策略仍需控制显存峰值，这一点在后续分片与批调度部分展开。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-5\">五 · 旧方案的负样本与温度：两个被继承的复杂度</h3>\n<p>softmax 对比损失还带来两个工程复杂度，它们不会因为换目标函数自动消失，但会被重新定价。其一是负样本采样：softmax 的分母天然把批内所有非对角元素当负对，负对的“硬度”由批构成决定，工程上为了提升检索质量会做难负样本挖掘、跨批队列等机制，这些机制在服务侧表现为额外的嵌入存储与索引维护成本。其二是温度调节：温度 τ 控制 softmax 分布的锐度，训练时对 τ 敏感，推理时点积排序要复现同一约定，否则排序漂移。sigmoid 形式把匹配判定变成逐对独立概率，负对由批内非对角元素直接给出标签 0，温度与偏置项成为可单独调优的超参，论文对此做了消融但未给出具体数值，部署时应作为独立超参处理。</p>\n<p>代价层面的具体表现：难负样本队列需要把历史批的嵌入留在显存或主机内存里，队列长度与批大小共同决定显存占用；温度错配会让同一嵌入在不同服务副本上给出不同 top-k，运维只能靠固定 τ 与归一化约定来压差异。sigmoid 路径下，负对数量仍随批增大而增多，批构成偏差会引入噪声标签，因此监控批内正负比例与嵌入范数分布成为服务侧的常规指标。一个具体机制例子：检索服务在低峰期请求稀疏，本地批只有 4 条，softmax 训练出的嵌入在该批下负对极少，排序退化；而 sigmoid 训练的嵌入对每对独立判定，4 条批仍能给出稳定的匹配概率，代价是相似度矩阵只有 4×4，显存压力小，但单批吞吐低，需要用多副本并行来补。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-6\">六 · 落到工程判断：这条路径在 Blackwell 栈上的位置</h3>\n<p>把旧方案的痛点收敛成一句工程判断：softmax 对比损失把批变成了全局同步对象，服务侧的延迟、吞吐、显存与带宽四笔账都被这个对象绑架；sigmoid 损失把批还原为本地数据单位，让双塔可以独立前向、独立分片、独立扩缩容。对 Blackwell（SM100/SM103）上的推理栈而言，这条路径的价值在于结构可分解：图像编码器与文本编码器可分别做并行切分与批调度，相似度矩阵的计算可以按本地批上限切片，避免 N×N 峰值显存一次性驻留；检索与零样本分类只需双塔前向加点积排序，适合低延迟服务的拆分部署。需要明确的是，论文未给出 NVFP4/FP8 量化、KV cache、分离式预填/解码与 Blackwell 硬件档位的部署数据，视觉编码器在低精度下的精度损失需单独评估，容量规划不能直接套用训练结论。</p>\n<p>具体机制上，部署时应把本地批上限作为一等参数：相似度矩阵规模为批大小平方，显存峰值与批调度、分片策略强耦合，盲目增大本地批会导致 OOM；负对由批内非对角元素构成，批构成变化影响噪声标签比例，需监控批内正负比例与嵌入范数分布。一个工程判断的例子：在 GB200 NVL72 这类高带宽域内，双塔独立前向可以把图像与文本编码器放在不同副本上并行，相似度计算按本地批切片后做点积排序，通信只发生在嵌入汇聚处而非 logits 全局归约处，跨设备同步需求显著低于 softmax 路径；但若把本地批推到显存上限，N×N 矩阵仍会成为峰值，需与批调度配合。这条从全局归一化到逐对独立的转向，正是后续分片、批调度与低精度推理讨论的起点。</p>\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-7\">七 · 请求形态：检索、零样本分类与嵌入批</h3>\n<p>把这篇论文的双塔结构放到推理服务里，请求形态不是单一的“生成”，而是三类可分解的嵌入计算：图文检索（单图对多文本、单文本对多图）、零样本分类（图像对类别名文本集合）、以及批量嵌入离线任务。三类请求的共同点是双塔独立前向、点积排序，差异在于候选集合规模与排序语义。检索请求的候选数由召回路数决定，零样本分类的候选数等于类别数，离线嵌入任务的候选数由批构造决定。这三种形态对显存的压力点不同：检索压在图侧单次前向与文本候选的批量嵌入，零样本分类压在类别文本嵌入的复用与图像嵌入的批规模，离线任务压在相似度矩阵的平方项。</p>\n<p>测量口径必须把“请求”与“对”分开计数。一个检索请求含 1 个图像嵌入与 K 个文本嵌入，产生 K 个图文对；一个零样本分类请求含 1 个图像嵌入与 C 个类别文本嵌入，产生 C 个对；离线批含 B 个图像与 B 个文本，产生 B² 个对。服务侧应分别记录请求数、嵌入数、对数三个量，否则吞吐数字不可比。可核查的口径是：每秒请求数、每秒嵌入数、每秒对数、以及每个请求的候选数分布（p50/p95/p99）。论文本身未给出这些数值，部署时必须自建基线。</p>\n<p>具体机制上，文本候选嵌入可缓存。零样本分类的类别名文本集合在服务生命周期内不变，其嵌入只需计算一次并驻留显存或主机内存，后续请求只做图像侧前向与点积。这把零样本分类的代价从“双塔前向”降为“单塔前向 + 查表点积”，是双塔可分解结构带来的直接工程收益。检索侧若文本库固定，同理可预计算文本嵌入索引，请求只做图像编码与近邻搜索。代价转移到索引内存与检索延迟：索引越大，点积排序的带宽压力越大，需用分片与量化索引控制。</p>\n<div class=\"formula\">$$\\text{对数} = B_{\\text{img}} \\times B_{\\text{txt}},\\quad \\text{矩阵显存} \\approx 4 B_{\\text{img}} B_{\\text{txt}} \\text{ bytes (fp32)}$$</div>\n<p>这个平方项是负载塑造方案的核心约束。B=1024 时矩阵约 4 MB，尚可接受；B=8192 时约 256 MB，已与编码器激活竞争显存。工程判断是：把“批大小”拆成图像批与文本批两个独立维度，检索请求天然是非对称的（1 图对 K 文），不应强制方形批。方形批只在离线对称任务里出现，服务侧应避免。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-8\">八 · 输入长度分布：文本侧的长尾与图像侧的固定成本</h3>\n<p>文本编码器的输入长度分布决定文本塔的算力与显存。检索查询通常是短文本（几个词到一句描述），零样本分类的类别名更短，长尾来自用户自由输入的描述性查询与多语言文本。图像侧则相反：分辨率固定，编码器算力与显存基本恒定，与文本长度无关。这种不对称意味着双塔的批调度不能共用一套长度分桶策略。文本塔按 token 长度分桶做连续批处理，图像塔按分辨率与批大小做固定形状调度。</p>\n<p>测量口径要记录文本 token 长度的分位数（p50/p90/p99/max）与截断率。截断率是长尾的直接指标：超过最大长度的请求被截断，检索质量下降但不报错，属于静默失败。服务应把截断率作为 SLO 的一部分暴露，而不是只监控延迟。图像侧记录分辨率分布与预处理耗时占比，因为解码与 resize 常是图像塔前的隐藏瓶颈。</p>\n<p>具体机制上，文本塔可用分桶加 padding 的批处理，桶边界按分位数设定，桶内 padding 浪费与桶间调度延迟需权衡。桶越细，padding 浪费越小，但批聚合等待越长，尾延迟上升。这是负载塑造方案的典型回路：为了压 p99 延迟而细化分桶，反而因等待聚合推高 p99。可核查的做法是固定桶边界、记录每桶的批填充率与等待时间，用填充率低于阈值的桶合并。</p>\n<p>代价落在显存与带宽：文本塔的激活显存随桶内最大长度线性增长，长尾请求会把整桶的显存峰值抬高。工程上把长文本请求路由到独立的长序列队列，与短请求隔离，避免一个长请求拖垮整批的显存预算。图像塔的固定成本则意味着图像批大小直接决定显存峰值，与文本长度无关，两个塔的容量规划应分开做。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-9\">九 · 并发、批大小与 SLO：平方项如何反过来限制负载</h3>\n<p>并发请求数不等于批大小。连续批处理下，批大小由调度器在延迟预算内动态聚合，并发是到达率与驻留时间的乘积。双塔服务的特殊之处是两塔可异步：图像塔与文本塔各自成批，相似度计算在两者都完成后进行。这允许两塔独立扩缩容，但也引入跨塔的批对齐问题——图像批与文本批的完成时间不匹配时，相似度矩阵计算会等待，尾延迟被放大。</p>\n<p>SLO 的定义要分两层：嵌入计算延迟（单塔前向）与排序延迟（点积与 top-k）。检索服务的用户感知延迟是两者之和加网络。可核查的口径是分别埋点两塔前向耗时、矩阵计算耗时、top-k 耗时，并记录批大小与队列深度的联合分布。只报端到端延迟无法定位平方项瓶颈。</p>\n<div class=\"formula\">$$\\text{吞吐}_{\\max} \\approx \\frac{B_{\\text{img}} B_{\\text{txt}}}{t_{\\text{img}} + t_{\\text{txt}} + t_{\\text{mat}}(B_{\\text{img}},B_{\\text{txt}})}$$</div>\n<p>平方项反过来限制负载的方式很直接：当矩阵计算时间 t_mat 随 B² 增长并超过两塔前向时间之和时，继续增大批不再提升吞吐，只增加尾延迟与显存峰值。工程判断是找到 t_mat 与前向时间相等的拐点批大小，把调度上限设在该拐点附近，而不是按显存上限设批。论文未给出该拐点的实测值，部署时需用二分法在目标硬件上扫批大小，记录吞吐与 p99 延迟的联合曲线。</p>\n<p>具体例子：检索服务在固定文本索引下，文本塔可预计算，t_txt 趋近于零，瓶颈转为图像塔前向与矩阵点积。此时增大图像批能摊薄图像塔的权重读取带宽，但矩阵显存随图像批线性增长（文本批固定为索引规模），需按索引规模反推图像批上限。这是“方案限制负载”的实例：索引越大，允许的图像批越小，单请求的候选数上限被显存预算硬约束。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-10\">十 · 长尾：候选规模、冷启动与负对噪声</h3>\n<p>长尾在双塔服务里有三个来源。其一是候选规模的长尾：少数请求带超大候选集合（如全库检索），其矩阵计算时间远超中位数。其二是冷启动长尾：新类别文本或新文本库首次请求需计算嵌入，无缓存可用，延迟突增。其三是批构成长尾：离线对称任务里，批内负对比例随批构成波动，影响排序质量但不影响延迟，属于质量长尾。</p>\n<p>测量口径上，候选规模长尾用候选数的 p99/p999 与对应延迟分位数刻画；冷启动长尾用缓存命中率与首次请求延迟刻画；批构成长尾用批内正负对比例分布刻画。三者应分开上报，混在一个尾延迟指标里无法归因。可核查的做法是给每个请求打标签（候选规模桶、缓存命中与否、批类型），按标签聚合延迟。</p>\n<p>具体机制上，超大候选请求应走独立队列并限制并发，避免其矩阵计算占满显存带宽拖累其他请求。冷启动可用预热：服务启动时批量计算常用类别文本嵌入，把首次请求的延迟摊到启动阶段。批构成长尾则需在离线任务里固定正负对比例或分层采样，论文提到批构成变化会影响负对数量与噪声标签比例，部署时应把批内正负比例作为监控项。</p>\n<p>代价是显存与调度复杂度：独立队列意味着显存预留，预热意味着常驻内存。工程判断是长尾治理的收益必须用 SLO 违约率衡量，而不是用平均延迟。若 p99 延迟由候选规模长尾主导，隔离队列的收益远大于优化中位数路径。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-11\">十一 · 负载塑造方案，方案限制负载：双向回路与可核查口径</h3>\n<p>负载塑造方案的方式有三条：批大小上限由平方项显存决定；文本分桶由长度分布决定；候选规模隔离由长尾决定。方案反过来限制负载的方式同样有三条：批上限限制了单请求可携带的候选数，分桶边界限制了可接受的最大文本长度，隔离队列限制了超大候选请求的并发。这是一个双向回路，容量规划必须同时解两端，不能只按到达率做静态估算。</p>\n<p>可核查的测量口径应包含：请求到达率与并发数的时间序列；批大小与队列深度的联合分布；两塔前向耗时、矩阵耗时、top-k 耗时的分位数；显存峰值与带宽利用率；缓存命中率；截断率与候选规模分位数；批内正负对比例。这些指标足以复现容量拐点，且不依赖论文未给出的数值。</p>\n<table class=\"mini\"><thead><tr><th>口径</th><th>测量对象</th><th>用途</th><th>代价信号</th></tr></thead><tbody><tr><td>每秒对数</td><td>B_img × B_txt</td><td>吞吐归一化</td><td>矩阵显存与带宽</td></tr><tr><td>候选数 p99</td><td>每请求 K 或 C</td><td>长尾隔离阈值</td><td>排序延迟</td></tr><tr><td>文本长度 p99</td><td>token 数</td><td>分桶边界</td><td>激活显存峰值</td></tr><tr><td>缓存命中率</td><td>文本嵌入复用</td><td>冷启动治理</td><td>常驻内存</td></tr><tr><td>批内正负比</td><td>离线对称批</td><td>质量长尾监控</td><td>排序质量</td></tr></tbody></table>\n<p>具体例子：零样本分类服务把类别文本嵌入预热后，单请求只做图像塔前向与 C 次点积。此时负载塑造方案的方式是固定 C 与图像批上限；方案限制负载的方式是 C 越大，图像批上限越小，因为点积的中间结果显存随 C 线性增长。若 C 进入长尾（数千类），需把点积分块，用带宽换显存，代价是延迟上升。这个回路在论文的双塔框架内是可推导的，但论文未给出部署数据，需在目标硬件上实测拐点。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-12\">十二 · 与 Blackwell 部署的接口：哪些结论可直接用，哪些必须实测</h3>\n<p>论文的可用结论是结构性的：双塔可独立前向、损失可分解到本地批、相似度矩阵平方增长。这三条直接映射到推理侧的拆分部署与批上限设定。不可直接用的是任何性能数字：论文未给出 NVFP4/FP8 量化、KV cache、分离式预填/解码与 Blackwell 硬件档位的部署数据。视觉编码器在低精度下的精度损失、嵌入范数分布的变化、点积排序的稳定性，都必须单独实验。</p>\n<p>具体机制上，图像塔可用 FP8 或 NVFP4 做权重与激活量化以压带宽，但嵌入需保持足够精度做点积排序，量化误差会直接改变 top-k 顺序。可核查的做法是对比量化前后同一批请求的 top-k 重合率与嵌入范数分布，重合率低于阈值则回退图像塔精度。文本塔的量化相对安全，因为文本嵌入的候选集合通常较小，排序对微小误差不敏感。</p>\n<p>代价落在显存与功耗：低精度量化降低显存带宽压力，允许更大图像批，但矩阵计算的平方项不因量化而消失，显存峰值仍由 B_img × B_txt 决定。工程判断是量化收益用于放宽图像批上限，而不是放宽候选规模上限；后者受排序质量约束，不能只靠精度换。</p>\n<p>最后落在调度器的具体机制上：调度器应以矩阵计算的显存预算为硬约束反推批大小，以两塔前向耗时的较小者为批聚合窗口，以候选规模分位数为隔离阈值。这三个参数在目标硬件上实测确定，不引用论文数值。服务上线后持续记录每秒对数、候选数分位数、缓存命中率与批内正负比，用拐点漂移判断是否需要重调批上限。这是把论文的结构性结论转成可运维容量的最小闭环。</p>\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-13\">十三 · 相似度矩阵的逐元素算子形态</h3>\n<p>sigmoid 损失把批内 N×N 相似度矩阵的每个元素都当成一次独立的二分类判定，这在算子层面意味着一个纯 elementwise 的融合 kernel：读入 s<sub>ij</sub>、标签 y<sub>ij</sub>，输出该元素的损失贡献，再沿两个维度归约。与 softmax 对比损失必须在整行上做 max、exp、sum 三趟归约不同，sigmoid 形式没有跨元素依赖，因此 kernel 可以完全并行、无需在片上缓存整行 logits。对 Blackwell 而言这一点尤其关键：SM100 的寄存器文件与 TMEM 容量有限，softmax 路径要把一行 N 个 logit 保持在片上做数值稳定化，N 增大时被迫溢出到共享内存或 HBM；而 sigmoid 路径可以按 tile 流式处理，每个 tile 算完即归约，片上占用与 N 解耦。</p>\n<div class=\"formula\">$$\\ell_{ij}=y_{ij}\\cdot\\log\\sigma(s_{ij})+(1-y_{ij})\\cdot\\log(1-\\sigma(s_{ij}))=-\\log\\sigma\\!\\left((2y_{ij}-1)\\,s_{ij}\\right)$$</div>\n<p>逐项解释：s<sub>ij</sub> 是 L2 归一化后图像嵌入与文本嵌入的点积，取值范围受归一化约束在 [−1,1]；y<sub>ij</sub>∈{0,1}，对角为 1、非对角为 0；(2y<sub>ij</sub>−1) 把标签映射为 ±1，于是正对要求 s 大、负对要求 s 小，两项合并为单一 log-sigmoid 形式。这个等价变形是 kernel 实现的核心：它把分支判断消掉，只剩一次符号翻转、一次乘加和一次 log-sigmoid。工程上应直接用 log1p/expm1 组合的数值稳定写法，避免先算 σ(s) 再取 log 造成 s 为大负数时的下溢。</p>\n<p>推理系统代价：该算子的算术强度极低（每元素约 10 次浮点运算、读写各一次），是典型的带宽受限 kernel。以 N=4096 的本地批为例，相似度矩阵有约 1678 万个元素，FP16 存储需约 33.6 MB，仅读一遍矩阵就构成可观的 HBM 流量；若在反向中还要重算或缓存中间量，显存峰值进一步抬升。因此部署时应把 logits 生成（GEMM）与损失归约（elementwise+reduce）分成两个 kernel，让 GEMM 的输出直接以低精度落盘、归约 kernel 再按 tile 流式读取，避免在 GEMM 的 epilogue 里塞入跨 tile 归约而破坏 2-SM MMA 的流水。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-14\">十四 · 双塔 GEMM 与 tcgen05 的落点</h3>\n<p>相似度矩阵本身是一次 GEMM：图像嵌入矩阵（N×d）乘以文本嵌入矩阵的转置（d×N）。在 Blackwell 上这条 GEMM 应由 tcgen05 指令族的 MMA 承担，累加器驻留 TMEM 而非寄存器堆。tcgen05 的关键变化是 MMA 由单个 SM 发起、可跨两个 SM 协作（2-SM MMA），两个 SM 的 Tensor Core 共同完成一个更大的 MMA tile，累加结果分布在两侧 TMEM 中。对双塔对比来说，这直接决定了 tile 形状的选择：d 通常为 512–1024 量级，N 可达数千，K 维（嵌入维度）相对短，属于“瘦高”GEMM，2-SM MMA 能把 N 方向的 tile 做宽，减少每个 tile 的发起开销与 TMEM 换入换出次数。</p>\n<div class=\"formula\">$$\\text{TC 利用率}\\approx\\frac{2\\,M\\,N\\,K}{t_{\\text{mma}}\\cdot P_{\\text{peak}}},\\qquad \\text{TMEM 占用}=M_{\\text{tile}}\\times N_{\\text{tile}}\\times\\frac{\\text{acc bits}}{32}$$</div>\n<p>逐项解释：分子是 2-SM MMA 一次协作完成的浮点运算量（乘加各计一次）；分母是 MMA 指令周期与该档位峰值算力之积，比值即 Tensor Core 实际占用率。第二式给出累加器在 TMEM 中的列占用：TMEM 按 32 位列组织，FP32 累加时每个元素占一列，tile 越大占用越多，超过 512 列即无法容纳，必须缩小 tile 或改用 FP16 累加。这解释了为什么低精度推理里累加精度的选择不是纯数值问题，而是直接决定 tile 形状与占用率的容量问题。</p>\n<p>具体例子：若把 N 方向 tile 定为 256、M 方向 128，FP32 累加需 128×256 列当量，远超单 SM TMEM 容量，必须走 2-SM 分摊或降 tile；而若累加改为 FP16，占用减半但仍受列数上限约束。工程判断是：相似度 GEMM 的 K 很短，MMA 的算术强度不足以掩盖 TMEM 搬运，因此应优先保证 tile 能一次装下、避免中间结果回写 HBM，而不是盲目追大 tile。推理侧代价体现在首 token 之外的批量排序阶段：这条 GEMM 的延迟与 N 成正比、与 d 成正比，是检索服务中随批增大最先恶化的环节。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-15\">十五 · 数据类型选择：FP16/BF16/FP8/NVFP4</h3>\n<p>双塔嵌入在 L2 归一化后动态范围被压缩到 [−1,1]，这使低精度表示相对友好，但不同数据类型的问题不同。FP16 尾数 10 位，在 [−1,1] 区间的绝对分辨率约 2<sup>−11</sup>，对点积排序足够；缺点是动态范围窄，若归一化前的投影输出出现较大值，FP16 易溢出，需要在投影头后做 clamp 或改用 BF16。BF16 尾数仅 7 位，分辨率约 2<sup>−8</sup>，在 s 接近 0 的区域会把正负对的微小差距抹平，导致排序抖动；但它的指数范围与 FP32 一致，不需要溢出保护。工程取舍是：图像编码器输出用 BF16 保动态范围，相似度 GEMM 的输入转 FP16 保分辨率，两者之间的转换点放在 L2 归一化之后。</p>\n<p>FP8（E4M3）尾数 3 位，分辨率约 2<sup>−4</sup>，直接把 s 量化到 1/16 的网格上。对 N 很大的批，正负对在 s 上的间隔往往小于该网格，量化噪声会淹没排序信号，因此 FP8 只适合放在 GEMM 的输入侧做吞吐加速，而损失计算与最终排序必须回到更高精度。NVFP4（E2M1 加块级缩放）尾数 1 位，单元素只剩符号与粗略量级，必须依赖 16 元素块的共享缩放因子恢复局部动态范围；它对嵌入向量的方向信息保留极差，直接用于相似度计算会破坏 L2 归一化的几何意义。可行路径是把 NVFP4 用在投影头的权重上而非激活上，让激活保持 FP8/FP16。</p>\n<table class=\"mini\"><thead><tr><th>类型</th><th>尾数位</th><th>[−1,1] 分辨率</th><th>适用位置</th><th>主要代价</th></tr></thead><tbody><tr><td>FP16</td><td>10</td><td>约 2⁻¹¹</td><td>相似度 GEMM 输入、损失计算</td><td>动态范围窄，需防溢出</td></tr><tr><td>BF16</td><td>7</td><td>约 2⁻⁸</td><td>编码器输出、投影中间量</td><td>近零区排序抖动</td></tr><tr><td>FP8 E4M3</td><td>3</td><td>约 2⁻⁴</td><td>GEMM 输入侧吞吐加速</td><td>量化噪声淹没小间隔</td></tr><tr><td>NVFP4</td><td>1</td><td>块缩放后粗粒度</td><td>投影头权重</td><td>方向信息损失大</td></tr></tbody></table>\n<p>推理系统代价：精度每降一级，GEMM 的吞吐提升来自 Tensor Core 峰值翻倍与 HBM 流量减半，但排序质量下降会直接反映为检索召回的下滑。以单图对多文本的检索请求为例，候选文本嵌入若用 FP8 存储，点积结果的噪声可能改变 top-1 与 top-2 的相对次序，服务侧表现为命中率下降而非延迟下降。因此低精度部署必须配套“粗排低精度、精排高精度”的两级结构，把 NVFP4/FP8 限制在候选规模大的粗排阶段。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-16\">十六 · 累加精度与误差传播</h3>\n<p>相似度 GEMM 的 K 维虽短，但累加精度的选择影响被 sigmoid 的非线性放大。FP16 输入配 FP16 累加时，K=512 的点积在部分和上累积舍入误差，误差量级随 √K 增长；若改用 FP32 累加，误差被压到可忽略。关键在于 log-sigmoid 在 s≈0 附近的导数最大（为 0.5），误差在此处被线性传递；而在 |s| 较大时导数趋近于 0，误差被压缩。这意味着累加误差对损失的影响集中在正负对难以区分的样本上，恰好是排序最不确定的那部分。</p>\n<div class=\"formula\">$$\\delta\\ell\\approx\\left|\\sigma(-s)-y\\right|\\cdot\\left|\\delta s\\right|,\\qquad \\left|\\delta s\\right|\\lesssim\\sqrt{K}\\cdot\\epsilon_{\\text{acc}}\\cdot\\left\\|q\\right\\|\\left\\|k\\right\\|$$</div>\n<p>逐项解释：第一式是损失对 s 的敏感度，系数 |σ(−s)−y| 在 s=0、y=1 时等于 0.5，在 s 远离 0 时趋近 0 或 1；第二式给出点积误差上界，ε<sub>acc</sub> 是累加精度的单位舍入误差，‖q‖‖k‖ 因 L2 归一化恒为 1，于是误差上界简化为 √K·ε<sub>acc</sub>。代入 FP16 累加（ε≈2<sup>−11</sup>）与 K=512，误差上界约 2<sup>−6</sup> 量级，乘以 0.5 的敏感度系数后仍足以改变 s 在 1/16 网格附近的判定。工程结论是：损失计算与最终排序必须用 FP32 累加，GEMM 主体可用 FP16 输入但累加器不得降到 FP16。</p>\n<p>具体例子：在零样本分类中，类别名文本嵌入与图像嵌入比对取最大，类别数可达上千。若累加用 FP16，两个语义相近类别的分数差可能小于累加误差，argmax 结果在请求间抖动，表现为同一图像在不同批次下分类结果不一致。这类不稳定在服务侧难以通过重试掩盖，必须在 kernel 层固定累加精度。推理系统代价是 FP32 累加使 TMEM 占用翻倍、tile 尺寸受限，吞吐相对 FP16 累加下降，但对排序正确性是必要支出。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-17\">十七 · Blackwell 特性对损失归约的约束</h3>\n<p>第五代 Tensor Core 的吞吐提升把瓶颈从 MMA 推到归约与数据搬运。sigmoid 损失的归约是 N×N 矩阵的全元素求和再除以 N，属于跨 tile 的全局归约。在 2-SM MMA 下，累加结果分布在两个 SM 的 TMEM 中，归约必须先做 TMEM→寄存器的搬运、再做 SM 内归约、最后跨 SM 合并。这条路径的代价不在算术而在 TMEM 读取带宽：TMEM 的读带宽虽高于 HBM，但每次搬运都有固定延迟，tile 越多、搬运次数越多，归约延迟随 tile 数线性增长。</p>\n<p>可行的做法是把归约拆成两级：每个 tile 在 epilogue 中先做局部求和并写入共享内存的原子累加槽，kernel 结束时只读一次槽位做最终除法。这样 TMEM 搬运次数等于 tile 数而非元素数，且原子操作在共享内存层面完成，不触发全局同步。对分离式预填/解码的部署形态，这条归约只出现在预填侧的批处理阶段，解码侧的单请求检索不涉及 N×N 矩阵，因此可以把归约 kernel 与解码 kernel 分属不同流，避免预填的归约延迟阻塞解码的 token 生成。</p>\n<p>推理系统代价：归约的显存流量与 N² 成正比，N=4096 时读一遍 FP16 矩阵约 33.6 MB，若归约 kernel 与 GEMM 未融合，这部分流量在 HBM 上重复一次，等效于把该阶段的带宽需求翻倍。功耗侧，Tensor Core 在低算术强度的瘦高 GEMM 上利用率不高，而 HBM 持续满速读写，能效比劣于算术密集的注意力 GEMM。工程判断是把相似度计算与损失归约合并进一个以 tile 为单位的流水 kernel，让矩阵块在片上完成“算—判—归约”三步后即丢弃，不落 HBM。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-18\">十八 · 从训练算子到推理服务的精度契约</h3>\n<p>论文未给出 NVFP4/FP8 量化与 Blackwell 部署数据，因此把训练侧的 sigmoid 结论直接搬到低精度推理服务存在明确的精度契约缺口。训练时损失在 FP32 下计算、嵌入在 BF16/FP16 下前向，收敛后的嵌入几何结构是在该精度下形成的；推理若把嵌入压到 FP8，相当于在服务侧引入训练时未建模的扰动，而 sigmoid 损失的逐对独立判定不会像 softmax 那样通过全局归一化吸收部分扰动——softmax 的温度与归一化会重新缩放 logits，sigmoid 没有这一层缓冲，量化噪声直接进入每个元素的判定。</p>\n<p>具体机制上的补救是校准偏置项：sigmoid 损失含可学习的偏置 b，使 σ(s+b) 的判定阈值偏离 0。低精度推理时若把 b 与 s 一同量化，b 的量化误差会整体平移判定阈值，造成系统性偏向（正对被判负或反之）。因此 b 应保持在 FP32 并与量化后的 s 在更高精度下相加，再进入 log-sigmoid。这个加法在 kernel 中是每元素一次标量加，代价可忽略，但它是维持训练—推理精度一致的最小契约。</p>\n<p>推理系统代价最终落在容量规划上：相似度矩阵的 N² 显存与归约带宽决定了单卡可承载的本地批上限，而低精度只缓解存储、不缓解归约的流量结构。对检索服务，应按“粗排低精度大候选、精排 FP16/FP32 小候选”分层设定批上限，并把 sigmoid 偏置与温度作为独立于量化方案的超参在服务侧固定，避免批构成变化时判定阈值漂移。这条判断比任何单一数据类型的取舍都更影响排序稳定性。</p>\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-19\">十九 · 显存账本的三层结构与可复算预算</h3>\n<p>在 Blackwell 上部署双塔图文模型，显存不是一笔糊涂账，而是三层可分别核算的账本：权重（静态、常驻）、激活（前向瞬时、随批线性增长）、以及推理侧特有的 KV cache（自回归文本塔解码时随序列长度与并发线性增长）。三者叠加才是单卡可用显存的上限约束。以 B200 的 HBM3e 容量为锚，先写出通用预算式：</p>\n<div class=\"formula\">$$M_{\\text{total}} = \\underbrace{P \\cdot b_w}_{\\text{权重}} + \\underbrace{B \\cdot s \\cdot h \\cdot L \\cdot b_a \\cdot k}_{\\text{激活}} + \\underbrace{C \\cdot S \\cdot L \\cdot h \\cdot b_{kv} \\cdot 2}_{\\text{KV cache}} + M_{\\text{workspace}}$$</div>\n<p>其中 $P$ 为参数量，$b_w$ 为权重每元素字节数（NVFP4 约 0.5 字节加缩放因子开销，FP8 为 1 字节，BF16 为 2 字节）；$B$ 为本地批，$s$ 为序列长度，$h$ 为隐藏维，$L$ 为层数，$b_a$ 为激活字节数，$k$ 为激活驻留倍数（受重计算与融合影响）；$C$ 为并发解码序列数，$S$ 为上下文长度，$b_{kv}$ 为 KV 每元素字节数，因子 2 表示 K 与 V 两份。workspace 包含 cuBLAS/tcgen05 的 MMA 累加缓冲、NCCL 通信缓冲与分页表元数据。</p>\n<p>给出一个可复算的例子：文本塔取 $L=32$、$h=4096$、$P_t\\approx 7\\text{B}$，图像塔取 ViT 量级 $P_v\\approx 0.3\\text{B}$，合计约 7.3B 参数。权重在 FP8 下约 7.3 GB，NVFP4 下约 3.7 GB 加少量缩放开销。若并发 $C=64$、上下文 $S=4096$、KV 用 FP8（$b_{kv}=1$），KV cache 约为 $64\\times4096\\times32\\times4096\\times1\\times2 \\approx 68.7$ GB——这一项已经压过权重一个数量级，说明多模态检索服务的显存主矛盾在 KV 与并发，而非参数。激活项在 $B=256$、$s=512$ 时按上式估算为个位数 GB，属于可被批调度吸收的部分。工程判断由此得出：容量规划的第一优先级是 KV 预算，第二是权重精度，激活排第三。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-20\">二十 · 相似度矩阵的平方项：批上限的硬约束</h3>\n<p>双塔结构在推理时先各自前向得到 L2 归一化嵌入，再做点积排序。检索场景下相似度矩阵规模为 $B_i \\times B_t$（图像批乘文本批），零样本分类则是 $B_i \\times N_c$（类别数）。论文明确指出该矩阵随批大小平方增长，这是显存峰值与 OOM 的直接来源。矩阵本身在 FP16 下每元素 2 字节，$B=1024$ 时单矩阵即 2 MB 量级，看似不大；但反向与排序阶段需要保留中间量、top-k 索引与归一化副本，实际驻留是矩阵的常数倍，且与激活、KV 共享同一 HBM 池。</p>\n<p>控制手段有三：其一是本地批上限加梯度累积，把全局批拆成多个本地批分片，使平方项落在分片内而非全局；其二是分块点积，把 $B_i \\times B_t$ 拆成 $T\\times T$ 的 tile 逐块计算并即时归约 top-k，避免整矩阵物化；其三是把排序卸载到 CPU 或使用分段 top-k，仅回传候选索引。代价体现在延迟上：分块点积增加 kernel 启动次数与中间读写，单请求排序延迟上升；而批上限压低则直接损失吞吐。这是一个典型的吞吐—显存—延迟三角，工程上应以 SLO 的 P99 排序延迟反推最大 tile 与批上限，而不是先定批再测延迟。</p>\n<p>具体例子：一个以图搜文服务，图像塔单次前向 $B_i=64$，文本库候选 $B_t=8192$，若整矩阵物化需 $64\\times8192$ 个 FP16 元素并保留 top-k 缓冲；改为 $256$ 列的 tile 流式计算后，峰值显存降到单 tile 量级，代价是排序阶段多出若干次全局归约。Blackwell 的 tcgen05 与 TMEM 适合承载这类小 tile 的 MMA 累加，把点积与归约压进 Tensor Core 流水，减少中间张量落 HBM 的次数——这正是带宽账的关键。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-21\">二十一 · 带宽瓶颈的定位：HBM3e 与 KV 的读写比</h3>\n<p>推理性能的分水岭不在算力而在带宽。Blackwell 的 HBM3e 提供高带宽但容量有限，解码阶段每生成一个 token 都要把全部 KV 读一遍，算术强度极低，属于典型的 memory-bound。设单层 KV 读写量为 $2 \\cdot S \\cdot h \\cdot b_{kv}$，全模型为 $L$ 倍，则每 token 的 KV 流量为：</p>\n<div class=\"formula\">$$Q_{\\text{kv}} = 2 \\cdot L \\cdot S \\cdot h \\cdot b_{kv}\\ \\text{(bytes/token)}$$</div>\n<p>代入 $L=32$、$S=4096$、$h=4096$、$b_{kv}=1$，得每 token 约 1.07 GB 的 KV 读取量。若 HBM 带宽为每秒数 TB 量级，则单序列解码的理论上限被这一流量直接锁死；并发 $C$ 条序列时总流量线性放大，带宽成为吞吐天花板。这就是为什么 KV 量化（FP8 乃至更低）与分页管理不是可选项：$b_{kv}$ 减半即流量减半，直接换来吞吐翻倍的空间，代价是精度损失需在检索排序质量上单独验证。</p>\n<p>权重侧的带宽账不同：权重只在每 token 前向时读一遍，$P \\cdot b_w$ 与批大小无关，因此大批量下权重带宽被摊薄，而 KV 带宽随并发线性增长。这解释了连续批处理为何必须与分页 KV 配合——把变长序列的 KV 切成固定大小页，按需分配与回收，消除预留最大长度的浪费，同时让页表寻址的额外读放大可控。工程上应监控每 token 的实际 HBM 读写字节与理论值之比，偏离过大说明页表碎片或 kernel 融合不足。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-22\">二十二 · 分页、压缩、复用与卸载的组合策略</h3>\n<p>分页 KV 的核心是把逻辑序列映射到物理页，页大小取 16 至 64 token 量级以平衡碎片与寻址开销；前缀共享（同一系统提示或同一图像描述模板）可让多条请求复用同一批物理页，把复用率转化为显存节省。压缩则沿两个轴：KV 量化降 $b_{kv}$，以及按注意力稀疏性丢弃低权重 token 的 KV（需与检索排序的召回要求对齐，不能盲目丢）。复用还包括嵌入级缓存——热门图像或类别文本的嵌入可常驻，避免重复前向，这在零样本分类的固定类别集上收益显著。</p>\n<p>卸载（offload）把冷 KV 页或低频权重放到主机内存或 NVLink 可达的对端显存，用带宽换容量。代价是 PCIe 或 NVLink 传输延迟进入关键路径，必须与预取流水配合：在解码当前 token 时预取下一段所需页，把传输隐藏在计算之后。NVL72 机架内 NVLink 5 的高带宽使跨 GPU 的 KV 池化成为可行方案，把容量问题转化为拓扑与路由问题，但跨节点流量会与集合通信争抢带宽，需与并行策略统一规划。</p>\n<p>具体例子：一个多租户图文检索服务，类别集固定为数千类，文本嵌入可全量常驻并复用；图像侧请求突发，KV 主要来自描述生成的可选分支。此时把文本塔权重与嵌入常驻、图像塔按批调度、KV 按页分配并设上限，可在不扩容量的前提下稳定 P99。反之若把 KV 预留到最大上下文，显存利用率会跌到很低，突发并发直接触发 OOM。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-23\">二十三 · 精度与容量的联动：NVFP4/FP8 下的账本重算</h3>\n<p>精度选择直接改写预算式的每个系数。权重从 BF16 降到 FP8，$b_w$ 减半，容量与权重带宽同步减半；降到 NVFP4，$b_w$ 再减半但引入块缩放因子与反量化开销，需在 Tensor Core 流水内完成，否则反量化本身成为带宽负担。KV 从 BF16 降到 FP8，$b_{kv}$ 减半，解码流量减半，这是吞吐提升最直接的一刀。激活精度影响较小但不可忽略：视觉塔对低精度更敏感，工程上常对图像塔保留较高精度、对文本塔与 KV 激进压缩，形成非对称精度账本。</p>\n<p>重算预算时须把缩放因子与元数据计入：NVFP4 的块缩放按固定块大小存储，每块一个缩放值，等效每元素开销略高于 0.5 字节；分页表的页元数据、top-k 索引、归一化副本都是常数项但不能忽略。工程判断是：先按 BF16 算出容量基线，再逐项替换系数并复算峰值，任何一项替换都要在检索召回与排序质量上做对照，不能只看显存数字。论文未给出量化与 Blackwell 部署数据，因此上述系数替换属于部署侧独立实验范畴，不能直接引用其训练结论。</p>\n<table class=\"mini\"><thead><tr><th>账本项</th><th>驱动变量</th><th>随批/并发增长</th><th>主要代价</th></tr></thead><tbody><tr><td>权重</td><td>参数量、精度</td><td>不随批增长</td><td>常驻容量、权重带宽</td></tr><tr><td>激活</td><td>本地批、序列长</td><td>线性</td><td>峰值显存、重计算</td></tr><tr><td>相似度矩阵</td><td>批大小平方</td><td>二次方</td><td>排序延迟、OOM 风险</td></tr><tr><td>KV cache</td><td>并发、上下文、精度</td><td>线性</td><td>解码带宽、容量天花板</td></tr></tbody></table>\n<p>把这张表当作容量规划的检查单：任何一次扩容或精度调整，都应按行复算并定位增长最快的那一项。对双塔检索服务，平方项与 KV 项通常先撞墙；对零样本分类，类别数决定的矩阵宽度与文本嵌入常驻是主项。最终落在具体机制上——以 SLO 的 P99 延迟与召回下限为约束，反解出最大本地批、KV 页上限与精度组合，再把这组参数固化进批调度器与分页分配器，而不是靠经验留余量。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-24\">二十四 · 批内相似度矩阵的显存账本与平方项边界</h3>\n<p>把 sigmoid 损失搬到推理服务上，第一笔账不是权重，而是那个随批大小平方增长的相似度矩阵。设本地批为 <i>B</i>、共享嵌入维度为 <i>d</i>、相似度以 FP16 或 BF16 存放，则单份矩阵的字节数为 <i>B</i>²·2；若按分片切到 <i>G</i> 个设备、每设备持有 <i>B/G</i> 行，则每卡矩阵为 (<i>B/G</i>)²·2，但每行仍需与全部 <i>B</i> 个文本嵌入做点积，故文本侧嵌入必须全量可见或被广播。这就是双塔结构在检索形态下的真实代价：图像塔与文本塔可以独立前向，但相似度计算是二者的汇合点，汇合点的显存与带宽不随分片线性下降。</p>\n<div class=\"formula\">$$M_{\\text{sim}} = \\frac{2B^{2}}{G}\\ \\text{bytes},\\qquad T_{\\text{gemm}} \\approx \\frac{2B^{2}d}{F_{\\text{eff}}}$$</div>\n<p>以 B200 的 HBM3e 容量为参照做可复算预算：假设单卡可用显存扣除权重与运行时开销后剩 <i>C</i> 字节，则矩阵项允许的批上限为 <i>B</i> ≤ √(<i>G·C</i>/2)。工程判断是：当 <i>d</i> 为数百、<i>B</i> 上千时，矩阵项本身已进入百 MB 量级，与视觉编码器的激活峰值同阶；若再叠加 FP8 权重与 KV 无关的嵌入缓存，容量就吃紧。此时正确做法不是继续加批，而是把检索请求拆成「单图对多文本」的排序批，用较小的 <i>B</i> 换取更低的平方项，同时以流式方式逐块计算相似度、算完即释放，避免整块矩阵常驻。</p>\n<p>失效条件很明确：一是批构成偏差，负对由非对角元素构成，若一个批里正对被系统性稀释，sigmoid 的二分类标签分布就偏斜，损失稳定性下降，检索排序质量随之劣化；二是把训练结论直接套到低精度推理，论文未给出 NVFP4/FP8 量化与 Blackwell 档位的部署数据，视觉编码器在低精度下的嵌入范数漂移会直接改变点积排序，必须单独标定。系统代价上，平方项既吃容量也吃带宽：矩阵写回与逐元素 sigmoid 是访存密集型，若 <i>d</i> 较小而 <i>B</i> 较大，GEMM 的算术强度被拉低，瓶颈从 Tensor Core 转到 HBM 读写，此时提高分片数只缓解容量、不缓解单卡内的带宽压力。</p>\n<table class=\"mini\"><thead><tr><th>项</th><th>随批增长</th><th>瓶颈位置</th><th>控制手段</th></tr></thead><tbody><tr><td>相似度矩阵</td><td>二次方</td><td>HBM 容量 + 写带宽</td><td>本地批上限、逐块流式</td></tr><tr><td>双塔激活</td><td>线性</td><td>SM 占用与寄存器</td><td>分片前向、批调度</td></tr><tr><td>嵌入广播</td><td>线性×分片</td><td>NVLink 5 链路</td><td>all-gather 与计算重叠</td></tr></tbody></table>\n<p>落到具体例子：一个图文检索服务若每卡剩余容量只够放一份千级批的 FP16 矩阵，那么把批翻倍就会直接触发 OOM，而不是渐进变慢——这是平方项与线性项叠加后的非线性拐点。可复算的判据是先用上式估出矩阵项，再与视觉编码器激活峰值相加，若总和超过可用容量的七成，就应把批拆小并改用分块点积；同时监控批内正负比例与嵌入范数分布，把这两项作为是否放宽批上限的前置条件。至于 KV cache 与分离式预填/解码，本方案的双塔前向不产生自回归 KV，容量评估应聚焦嵌入缓存与矩阵项，不要照搬 LLM 的 KV 账本。</p>\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-25\">二十五 · 从训练批到服务批：可分解损失如何改写调度约束</h3>\n<p>sigmoid 损失把批内每个图文对当作独立二分类样本，损失对全部对求和后归一化，因此不需要跨设备对 logits 做全局归一化同步。这一性质在训练侧降低了通信需求，在推理侧则直接改写了批调度的自由度：图像编码器与文本编码器可独立前向，服务端不必为了凑出一个“全局对齐”的超大批而阻塞请求。代价从通信转移到本地相似度矩阵——规模为批大小平方。设本地批为 B、嵌入维度为 d，相似度矩阵元素数为 B²，其显存占用近似为</p>\n<div class=\"formula\">$$M_{\\text{sim}} \\approx B^{2}\\cdot b_{\\text{elem}},\\qquad C_{\\text{sim}} \\approx 2B^{2}d$$</div>\n<p>其中 b_elem 为单个相似度元素的字节数（FP32 为 4、FP16/BF16 为 2）。这意味着调度器不能像纯自回归解码那样无限堆积请求：检索类请求的批上限由 B² 项而非 KV 线性项主导。工程判断是，把“批”拆成两级——请求级微批（决定相似度矩阵规模）与设备级分片（决定单卡峰值显存），中间用 chunked 方式切分文本侧候选集。举例：单图对多文本检索，若候选文本 4096 条、嵌入维度 768，一次性构造 1×4096 相似度仅约 16K 元素，显存可忽略；但若把 64 张图与 4096 条文本做全交叉，矩阵膨胀到 64×4096，调度就必须先按图像分片再按文本 chunk 归并排序。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-26\">二十六 · 连续批处理与 chunked prefill：把平方项摊到时间轴上</h3>\n<p>连续批处理（continuous batching）的核心是迭代级调度：每个 decode step 结束后立即回收已完成序列、插入新请求，而不是等整批结束。对双塔检索服务，这一机制对应“嵌入计算流水线”——图像塔与文本塔各自维护在途批，任一塔完成一个微批就释放其相似度矩阵分块，不必与另一塔同步。chunked prefill 则把长文本候选（如类别名列表、长描述）切成固定 token 块，逐块前向并与已缓存的图像嵌入做部分点积，避免单个长请求独占一个 step 造成尾延迟尖峰。伪代码思路如下：</p>\n<ul>\n<li>维护两个队列：图像队列按到达时间排序，文本队列按候选集长度分桶；</li>\n<li>每个调度周期取 min(剩余显存预算 / B² 系数, 队列头请求数) 作为本周期微批上限；</li>\n<li>文本侧按 chunk_tokens 切块，块内做前向并写入分块相似度缓冲；</li>\n<li>当某请求的全部分块完成，触发 top-k 归并排序并回传，释放其缓冲。</li>\n</ul>\n<p>系统代价体现在两个方向：chunk 太小则 kernel 启动与调度开销占比上升，吞吐下降；chunk 太大则单请求占用相似度缓冲时间变长，尾延迟上升。一个具体例子是零样本分类：类别数 1000、每类文本 8 个 token，若 chunk 设为 64 token，则每请求约 125 个 chunk，调度器需保证这些 chunk 在多个 step 内交错执行，否则单请求延迟被拉长到与批内其他请求无关的水平。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-27\">二十七 · 优先级与抢占：尾延迟的两种压缩手段</h3>\n<p>检索与零样本分类的 SLO 通常由 P99 而非均值定义。尾延迟来源有三类：相似度矩阵分块的排队等待、长候选集的 chunk 串行化、以及显存峰值触发的 OOM 回退。优先级调度给交互式请求（单图单查询）更高权重，使其微批优先获得相似度缓冲；抢占则允许调度器在显存紧张时驱逐低优先级请求的中间分块，把缓冲让给高优先级请求，被驱逐请求稍后重算。代价是重算带来的额外前向计算——若被驱逐请求已完成 70% 的文本 chunk，重算成本约为其总计算量的 0.7 倍，吞吐损失与抢占频率成正比。工程上应设置抢占阈值：仅当剩余显存低于安全水位（例如相似度缓冲预算的 15%）时才触发，且优先驱逐候选集最长的请求，因为其单位重算收益最高。</p>\n<p>公式化地看，单请求的期望尾延迟可近似为排队延迟与分块串行延迟之和：</p>\n<div class=\"formula\">$$T_{99} \\approx \\frac{Q}{R_{\\text{buf}}} + \\left\\lceil \\frac{L}{c} \\right\\rceil \\cdot t_{\\text{chunk}}$$</div>\n<p>其中 Q 为排队请求的相似度元素总量，R_buf 为单位时间可处理的相似度元素吞吐，L 为候选 token 长度，c 为 chunk 大小，t_chunk 为单 chunk 前向时间。压低 T_99 的杠杆是提高 R_buf（分片并行、低精度点积）与减小 L/c 的串行深度（增大 chunk 但受显存约束）。注意，这里不涉及 KV cache 的线性增长——双塔检索的文本侧通常只做一次前向，不保留自回归 KV，因此抢占的代价主要是重算而非 KV 换出。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-28\">二十八 · 分离式预填/解码在双塔检索中的映射</h3>\n<p>分离式预填/解码（disaggregated prefill/decode）原本用于自回归生成，把计算密集的 prefill 与访存密集的 decode 放到不同资源池。映射到双塔检索服务，可拆成“嵌入预填池”与“相似度归并池”：前者负责图像塔与文本塔的前向，产出 L2 归一化嵌入并写入嵌入存储；后者负责点积、top-k 归并与排序回传。两池之间通过高速互联传递嵌入向量，而非传递原始像素或 token。这样做的收益是资源配比可按负载形态调整——检索高峰时归并池扩容，零样本分类高峰时预填池扩容。代价是嵌入传输带宽：单条 768 维 FP16 嵌入为 1.5 KB，若每秒处理数千条候选，跨池带宽需求进入数十 MB/s 量级，在 NVLink 5 域内可忽略，但跨节点时需计入 NIXL 传输开销。一个具体例子是图文检索服务：图像塔在预填池完成编码后，把嵌入写入分片存储；归并池按请求拉取候选文本嵌入做点积，若候选文本已预编码则无需再跑文本塔，尾延迟主要由归并池的排序与网络往返决定。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-29\">二十九 · 批构成与负对噪声：调度器必须监控的隐性成本</h3>\n<p>sigmoid 损失的负对由批内非对角元素构成，批构成变化会改变负对数量与噪声标签比例。推理侧虽不做反向传播，但若服务把“批内排序”当作检索结果的一部分（例如批内重排、去重），批构成偏差会直接影响排序质量。调度器应监控三个量：批内正负比例、嵌入范数分布、以及相似度分块归并前后的 top-k 重叠率。重叠率骤降说明分块归并引入了排序偏差，通常源于 chunk 边界处的数值累积或分片间未做全局归一化。工程判断是，在分片归并时对每片 top-k 做分数校准（按片内最大值缩放），再合并，避免大片与小片直接比较造成长尾候选被系统性压低。这一校准的计算量随分片数线性增长，远小于 B² 项，属于可接受的调度开销。</p>\n<table class=\"mini\"><thead><tr><th>调度手段</th><th>主要收益</th><th>系统代价</th><th>适用形态</th></tr></thead><tbody><tr><td>连续批处理</td><td>回收在途批、提升嵌入吞吐</td><td>调度开销、分块缓冲管理</td><td>高并发检索</td></tr><tr><td>chunked prefill</td><td>压低长候选集尾延迟</td><td>kernel 启动占比上升</td><td>零样本分类、长描述</td></tr><tr><td>优先级与抢占</td><td>保交互式 P99</td><td>重算计算量、吞吐损失</td><td>混合 SLO 服务</td></tr><tr><td>分离式预填/归并</td><td>资源配比弹性</td><td>嵌入跨池传输带宽</td><td>大规模图文检索</td></tr></tbody></table>\n<p>最后落在具体机制上：调度器的批上限不应由单一显存水位决定，而应由相似度矩阵预算 B²·b_elem 与嵌入存储带宽共同约束；当 B 增大到使 B² 项超过分片缓冲预算时，正确动作是切分候选集而非缩小全局批，因为 sigmoid 损失的可分解性允许本地批独立计算，切分不破坏损失语义，只影响批内负对构成——这正是调度与目标函数耦合的地方。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-30\">三十 · 批大小平方项如何反过来约束调度：从本地批上限到检索服务的尾延迟</h3>\n\n<p>把 sigmoid 损失搬到推理服务里，第一个会咬人的约束不是损失函数本身，而是相似度矩阵的二次方规模。检索请求的形态是“一图对多文”或“一文对多图”，若把候选文本全部塞进一个本地批，矩阵元素数为 <span class=\"formula\">$$M = B^2$$</span>，其中 B 为本地批内图文对数量；显存峰值近似正比于 M 乘以每元素字节数，在 FP8 或 NVFP4 下每元素仅占 1 字节或 0.5 字节，但 B 翻倍仍使矩阵占用翻四倍。这意味着连续批处理（continuous batching）在双塔检索上不能沿用解码器那套“能塞就塞”的策略：解码侧 KV cache 随序列长度线性增长，而这里的中间张量随批大小二次增长，调度器必须为每个请求维护一个“本地批上限”，把大候选集切成若干 chunk 分别前向再归并排序。切分带来的代价是排序阶段的额外合并开销与多次 kernel 启动，单请求尾延迟被拉长；收益是显存峰值可控、不会因个别大请求触发 OOM 而拖垮整个 batch。</p>\n\n<p>chunked prefill 的思路在这里要改写。文本编码器处理类别名或候选描述时，序列通常短而数量多，真正的瓶颈是矩阵构造与逐元素二分类计算，而非注意力长度。可行的做法是把候选集按固定大小分块，每块与图像嵌入做点积得到子矩阵，逐块计算 sigmoid 概率后只保留 top-k 候选进入下一轮，而不是把全矩阵物化后再排序。这样显存从 O(B²) 降到 O(B·k)，代价是分块边界处的排序不再全局精确——若 top-k 跨越块边界，需要保留每块的局部 top-k 再做一次小规模归并。工程判断是：当候选数远大于 k 时，分块加局部 top-k 的近似排序在检索质量上损失有限，但尾延迟显著下降；当候选数与 k 同量级时，分块反而增加归并开销，应直接整批计算。</p>\n\n<p>优先级与抢占在双塔服务里表现为编码器资源的争抢。图像编码器与文本编码器可独立前向，这给分离式部署提供了天然切分：图像侧走视觉塔，文本侧走文本塔，两侧的批调度互不阻塞。但两侧的负载特征不同——图像塔单请求计算重、批内请求数少；文本塔单请求轻、候选数量大。若共用一张 GPU 做连续批处理，文本塔的长候选批会占住 SM 与显存，图像塔的请求被迫排队，尾延迟由慢侧决定。抢占策略应允许调度器在图像请求到达时打断文本侧的大批，把文本批切小或延后，代价是文本侧吞吐下降、部分已计算的子矩阵作废。更稳的做法是按 SLO 分级：交互式检索请求走高优先级小批，离线批量重排走低优先级大批，两者在时间上错峰而非在同一 batch 内混跑。</p>\n\n<p>尾延迟的压缩最终落在“批内正负比例”这一非显性代价上。sigmoid 损失把每个非对角元素都当负对，推理时若把无关候选大量混入同一批，矩阵中负对占比升高，逐元素计算量不变但有效排序信号被稀释；更关键的是，负对噪声会改变 top-k 的边界，使分块归并时的候选保留策略失准。监控批内正负比例、嵌入范数分布与分块归并的候选召回率，比单纯盯吞吐更能定位尾延迟来源。论文未给出 Blackwell 上的量化与分离式部署数据，因此容量规划时应把矩阵显存、分块归并开销与编码器争抢三项分别做压力测试，而不是套用训练侧“小批即可”的结论直接上线。</p>\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-31\">三十一 · 从全局归一化到本地可分解：通信需求的结构性变化</h3>\n<p>softmax 对比损失的通信代价不是可选的工程细节，而是目标函数本身的结构性要求。全局批内归一化意味着每张卡算出的 logits 必须汇聚成完整的相似度矩阵，再对每一行做 softmax 归一化——这天然要求一次跨设备的 All-Gather 或 All-Reduce，且归一化后的梯度还要沿同一路径反向散射。批越大，汇聚的矩阵越宽，同步点的等待时间越长，通信与计算的重叠窗口越难排布。sigmoid 损失把每个图文对视为独立二分类，损失在本地批内即可闭合：</p>\n<div class=\"formula\">$$\\mathcal{L}=-\\frac{1}{N}\\sum_{i=1}^{N}\\sum_{j=1}^{N}\\left[y_{ij}\\log\\sigma(s_{ij})+(1-y_{ij})\\log(1-\\sigma(s_{ij}))\\right]$$</div>\n<p>注意这个求和的下标范围是本地批的 N，而非全局批。梯度只依赖本地相似度矩阵的对角与非对角元素，反向传播不需要等待其他设备上的 logits。这是并行策略选择的根本约束变化：softmax 下 DP 的扩展受制于全局批的同步频率，sigmoid 下 DP 可以退化为“各卡独立算本地损失、只在参数梯度上做一次 All-Reduce”，同步点从每个 micro-batch 的 logits 层降到参数更新层。代价也随之转移：既然不再靠全局负样本提供对比信号，负对的多样性与质量就完全由本地批构成决定，通信省下来的时间必须用批构造策略补回去。</p>\n<p>具体例子：在 GB200 NVL72 的一个 8 卡 NVLink 域内跑双塔预训练，softmax 方案每步要在相似度矩阵维度上做一次跨卡汇聚，矩阵规模随全局批平方增长，汇聚张量本身就可能成为带宽瓶颈；sigmoid 方案把这一步删掉，8 卡各自持有本地批的相似度矩阵，只在反向末段做一次梯度 All-Reduce。对推理侧而言，这个结构差异的直接后果是：双塔的嵌入计算可以彻底按请求维度切分，检索排序阶段的点积不需要跨设备归一化，服务编排可以把图像塔与文本塔放在不同并行组里独立伸缩。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-32\">三十二 · TP/EP/PP/DP 四种切分在双塔上的落点</h3>\n<p>双塔结构的并行切分不是均质的。图像编码器是稠密视觉主干，文本编码器是另一套稠密主干，两者之间只有最后的投影与相似度计算耦合。这决定了四种切分的适用边界：</p>\n<ul>\n<li><b>DP（数据并行）</b>：双塔最自然的切分。每卡持有完整参数副本、处理不同图文对，梯度 All-Reduce 在参数维度上做。sigmoid 损失让 DP 的同步量从“logits + 梯度”降为“仅梯度”，是这套目标函数在工程上最直接的收益。代价是参数副本的显存占用随卡数线性增长，对视觉主干的激活显存不友好。</li>\n<li><b>TP（张量并行）</b>：把线性层按列/行切到多卡，每层前后各一次 All-Reduce。双塔的嵌入维度通常不大，TP 的通信量与计算量之比偏高，跨 NVLink 域做 TP 尚可，跨节点做 TP 会被 All-Reduce 延迟吃掉收益。推理时 TP 的价值在于把单卡放不下的视觉主干摊开，但要注意 TP 组内的 All-Reduce 与 batch 无关，小 batch 下通信占比更高。</li>\n<li><b>PP（流水并行）</b>：按层切段，段间只传激活。双塔各自可以独立做 PP，两塔之间没有流水耦合，因此 PP 的 bubble 只出现在各自塔内。推理场景下 PP 的代价是首 token 延迟被段数放大，对检索类请求（单次前向出嵌入）不友好；对零样本分类这种批量排序请求，PP 可以用较大 micro-batch 摊薄 bubble。</li>\n<li><b>EP（专家并行）</b>：双塔本身不是 MoE，EP 不直接适用。但若把多模态服务做成“视觉塔 + 语言塔 + 生成头”的复合系统，生成头若为 MoE 则 EP 的 All-to-All 会与双塔的 DP 组争抢同一张 NVLink 的带宽。这是部署时容易忽略的争用点：EP 的 All-to-All 是突发性、消息细碎的，DP 的梯度 All-Reduce 是大块连续的，两者在同一 NVSwitch 域内叠加会拉高尾延迟。</li>\n</ul>\n<p>一个具体判断：在 NVL72 机柜内，双塔预训练优先 DP + 必要时塔内 TP，把 PP 留给推理侧的大 micro-batch 场景；EP 只在复合服务里出现，且应与双塔的并行组做物理隔离或至少做时间片错峰。推理服务的容量规划要把“嵌入前向”和“排序”分开算：前者是计算密集、可 DP 扩展；后者是带宽密集的点积排序，规模随候选数线性增长而非平方。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-33\">三十三 · NVLink 5 与 NVSwitch：域内带宽的可用窗口</h3>\n<p>Blackwell 世代的 NVLink 5 与 NVSwitch 把单机柜内的 GPU 互连做成全互联域，GB200/GB300 NVL72 的 72 卡处于同一高带宽域内。这对双塔推理的意义在于：TP 组、DP 组的 All-Reduce 可以落在域内完成，不必跨节点走 InfiniBand，通信延迟的量级从“跨节点往返”降到“域内交换”。但带宽充裕不等于通信免费，关键看通信与计算的重叠窗口是否被排满。</p>\n<p>推理侧的双塔前向是短而宽的：一次请求的图像塔前向可能只有几十毫秒量级，TP 组内每层两次 All-Reduce，层数一多，All-Reduce 的固定启动开销就会累积成可观的比例。NVSwitch 的全互联降低了单次交换的跳数，但 All-Reduce 的算法开销（ring 或 tree 的步数）仍与组大小对数相关。工程上的做法是把 TP 组压到 2 或 4 卡、把剩余并行度给 DP，让 All-Reduce 的消息更大、次数更少；或者用异步通信把下一层的 All-Reduce 与当前层计算重叠，代价是显存里要多留一份中间缓冲。</p>\n<p>具体代价：假设视觉主干在 4 卡 TP 组内做前向，每层两次 All-Reduce，若单次 All-Reduce 的固定开销在微秒量级、层数在数十层，则通信开销在单请求延迟中占比不可忽略；而把同样的卡数改为 DP，通信变成每步一次梯度 All-Reduce（推理时甚至不需要），延迟结构完全不同。这就是为什么推理部署里 TP 的组大小要按“单卡能否放下 + 延迟预算”反推，而不是按训练时的习惯铺满。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-34\">三十四 · All-to-All 与 All-Reduce 的代价分野</h3>\n<p>All-Reduce 是规约型通信，消息大小与参数量或激活量成正比，适合大块连续传输，带宽利用率高。All-to-All 是分发型通信，每个 rank 向其余 rank 发送不同分片，消息细碎、模式不规则，在 EP 场景下尤为突出。两者的瓶颈位置不同：All-Reduce 怕的是组太大导致步数多、启动开销累积；All-to-All 怕的是消息碎片化导致有效带宽远低于峰值，以及目的 rank 不均衡造成的排队。</p>\n<p>对双塔系统，All-Reduce 出现在 TP 的层内与 DP 的梯度同步；All-to-All 出现在 EP 的 token 路由，或出现在把检索候选分发到多卡的排序阶段。后者的一个具体形态是：单图对多文本的检索请求，图像嵌入广播到多卡、每卡负责一部分文本候选做点积，这本质是一次小规模 All-to-All（或 Broadcast + Gather），候选数越多，分发与回收的通信量越大。此时瓶颈不在计算而在分发：候选文本嵌入若已在各卡常驻，则只需广播图像嵌入；若候选是动态的，则每次请求都要搬一遍文本嵌入，带宽随候选数线性增长。</p>\n<p>工程判断：把静态候选（类别名、固定语料库）的文本嵌入预分片常驻各卡，只广播查询侧嵌入，能把 All-to-All 降为一次 Broadcast；动态候选则要按候选数设阈值，超过阈值改用集中式排序而非分布式分发，避免细碎消息打满 NVLink。这与相似度矩阵的平方开销是两套账：前者是通信账，后者是显存账，容量规划要分开列。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-35\">三十五 · NIXL 传输：把嵌入搬运从计算路径上摘出来</h3>\n<p>NIXL 这类传输层的作用是把数据搬运从框架的计算图里解耦，做成独立的、可异步的传输原语。对双塔推理，最直接的用法是把图像塔产出的嵌入、文本塔产出的嵌入、以及候选库的嵌入分片，通过 NIXL 在 GPU 显存之间直接搬运，绕开主机内存的中转。这在分离式部署里尤其关键：图像塔与文本塔可能落在不同的并行组甚至不同的节点上，嵌入要跨组汇合才能做点积排序。</p>\n<p>伪代码思路：查询侧图像塔前向产出 <i>e_img</i>，文本塔产出 <i>e_txt</i>；排序节点通过 NIXL 注册的显存缓冲拉取两侧嵌入，在本地做点积与 top-k，再把索引回传。关键是把“拉嵌入”做成与下一批前向重叠的异步操作，让传输延迟藏在计算后面。代价是显存里要预留传输缓冲，且 NIXL 的注册与句柄管理有固定开销，请求粒度太细时这笔开销摊不薄。</p>\n<p>具体例子：零样本分类请求，类别名文本嵌入是静态的，可预计算并常驻排序节点；每次请求只需 NIXL 搬运一张图的嵌入，传输量小、延迟低。图文检索请求若候选库很大，则要把候选嵌入分片常驻多卡，查询嵌入广播，NIXL 在这里承担的是分片注册与按需拉取。判断标准是：单次传输量小于某个阈值时，NIXL 的固定开销占比过高，不如把排序拉回产生嵌入的那张卡上做。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-36\">三十六 · 通信何时成为瓶颈：三个可观测的信号</h3>\n<p>不要把“通信是瓶颈”当成定性直觉，它有三个可观测的信号。第一，通信时间占 step 时间的比例随并行组增大而上升——TP 组从 2 扩到 8，若单请求延迟不降反升，说明 All-Reduce 的步数与启动开销已经压过计算收益。第二，All-to-All 的有效带宽远低于链路峰值——消息碎片化或目的 rank 不均衡时，链路利用率上不去，此时加卡不解决排队。第三，梯度 All-Reduce 与 EP All-to-All 在同一 NVSwitch 域内时间重叠——尾延迟被拉高，说明并行组没有做时间或物理隔离。</p>\n<p>对 sigmoid 双塔，还有一个特有的信号：本地批上限被显存卡住而非被通信卡住。相似度矩阵随批大小平方增长，盲目增大本地批会让显存峰值先撞墙，通信反而还没成为瓶颈。这意味着容量规划的顺序应该是先定本地批上限（显存约束），再定并行组大小（延迟约束），最后看通信占比是否可接受。反过来，如果为了压通信而缩小并行组、放大本地批，就会撞上平方显存墙——两个约束是耦合的，不能单独调。</p>\n<p>落到工程判断上：在 NVL72 域内，双塔推理的默认配置应是 DP 为主、TP 组压到最小可行、PP 仅在需要大 micro-batch 摊薄 bubble 时启用；静态候选嵌入预分片常驻以消掉 All-to-All；NIXL 只用于跨组嵌入汇合且设传输量阈值。通信是否成为瓶颈，最终由“单请求延迟里通信占比”与“显存峰值是否先撞墙”两个数共同判定，而不是由并行度大小判定。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-37\">三十七 · 通信何时退居次席：sigmoid 分解对并行切分的边界影响</h3>\n<p>在 TP/EP/PP/DP 四类切分里，softmax 对比损失的痛点集中在 DP 维：全局批的 logits 归一化要求所有数据并行 rank 把相似度分块做 All-Gather 再 Reduce，通信量与全局批规模线性相关，且必须在前向末尾形成同步屏障。sigmoid 损失把归一化拆成逐对独立项，损失可在本地批内闭合，DP 组只需在反向时对梯度做一次 All-Reduce，不再搬运 logits。设全局批为 B、单卡本地批为 b、卡数为 W=B/b，则 softmax 方案每步需搬运的相似度元素量级为 <span class=\"formula\">$$C_{\\text{softmax}} \\propto B^2$$</span>，而 sigmoid 方案降为 <span class=\"formula\">$$C_{\\text{sigmoid}} \\propto W \\cdot b^2$$</span>，在 W 较大时后者显著更省。代价转移到本地：b² 的相似度矩阵必须落在一张卡上，b 的上限由显存而非带宽决定。</p>\n<p>这决定了失效边界。当模型双塔参数量大到单卡放不下、必须引入 TP 时，TP 组内每层前向仍需 All-Reduce 激活，这部分通信与损失形式无关，sigmoid 的收益被摊薄；此时瓶颈从 DP 的 logits 同步转回 TP 的逐层同步，NVLink 5 与 NVSwitch 的域内带宽成为主导项，跨节点则落到 NIXL 传输路径上。反过来，若双塔较小、可整卡容纳而只做 DP，sigmoid 让 DP 几乎只剩梯度同步，通信在总步时中的占比下降，系统从带宽受限转为显存受限——这是本方案真正的适用区间。</p>\n<p>工程判断应落在本地批上限与分片策略的耦合上。相似度矩阵 b² 与视觉编码器激活共同决定峰值显存，盲目放大 b 换取负对数量会先触发 OOM 而非提速；负对由批内非对角元素构成，b 缩小后负对噪声比例上升，需同步监控批内正负比例。推理侧双塔可独立前向，图像与文本编码器分别切分部署，检索只做嵌入点积排序，通信仅发生在嵌入汇聚处，与训练期的 DP 同步是两套代价模型，容量规划不可混用。</p>\n<table class=\"mini\"><thead><tr><th>切分维</th><th>softmax 方案通信</th><th>sigmoid 方案通信</th><th>主导代价</th></tr></thead><tbody><tr><td>DP</td><td>logits All-Gather + 归一化同步</td><td>仅梯度 All-Reduce</td><td>本地 b² 显存</td></tr><tr><td>TP</td><td>逐层激活 All-Reduce</td><td>不变</td><td>NVLink 域内带宽</td></tr><tr><td>PP/EP</td><td>与损失形式无关</td><td>不变</td><td>跨节点 NIXL 传输</td></tr></tbody></table>\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-38\">三十八 · 精度塌陷：从嵌入范数到排序翻转的链路</h3>\n<p>在双塔检索服务里，精度塌陷很少以“报错”的形式出现，它表现为排序质量在无声中下滑。sigmoid 损失把每个图文对当作独立二分类，推理时只做嵌入点积排序；一旦图像塔或文本塔的嵌入分布发生漂移，点积的相对次序就会翻转，而服务层看到的只是召回率缓慢走低。定位这类问题的抓手是嵌入范数与相似度分布：L2 归一化后每个嵌入应落在单位球面上，若某一侧的范数分布出现长尾或整体收缩，说明投影头输出已被低精度路径污染。工程上应把每批嵌入的范数均值、方差、以及批内相似度矩阵的对角均值与非对角均值作为常驻指标，与基线窗口比对。</p>\n<p>代价体现在监控开销上：每批额外做一次范数统计与矩阵均值归约，在本地批为 B 时引入 O(B²) 的读取量，与相似度矩阵本身同阶，因此监控采样率必须与批调度联动，不能对每个微批全量采集。具体例子：一个图文检索服务把图像塔切到 FP8 执行而文本塔保留 BF16，若不做跨塔范数对齐检查，点积会因两侧尺度不一致而系统性偏向某一侧，表现为“文本换图不换”的伪相关。诊断顺序应是先查两侧范数分布，再查相似度矩阵的对角与非对角间隙，最后才怀疑权重。</p>\n<div class=\"formula\">$$\\text{drift}=\\frac{1}{B}\\sum_{i=1}^{B}\\left|\\,\\|\\mathbf{v}_i\\|_2-1\\,\\right|+\\frac{1}{B}\\sum_{j=1}^{B}\\left|\\,\\|\\mathbf{t}_j\\|_2-1\\,\\right|$$</div>\n<p>该指标超过阈值即触发回滚到上一版精度配置，而不是继续在低精度路径上调温度或偏置项——论文明确指出温度与偏置项对 sigmoid 损失性能有影响且需单独调优，用超参去补偿数值误差只会掩盖根因。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-39\">三十九 · OOM：平方项与分片边界的错配</h3>\n<p>OOM 在双塔推理里几乎总是相似度矩阵的平方项与分片策略错配造成的。sigmoid 损失本身可分解到本地批，但推理侧的排序请求是“单图对多文本”或“单文本对多图”，候选集大小由请求决定而非由训练批决定。若把候选集直接铺成一个 B×B 矩阵而不做分块，显存峰值会随候选数平方上升。正确做法是把候选集切成固定大小的块，逐块计算点积并维护 top-k 堆，使峰值显存与块大小成正比而非与候选总数平方成正比。</p>\n<p>代价核算要落到具体档位：B200 的显存容量决定了单卡可容纳的块大小上限，而块内矩阵的元素数与嵌入维度相乘即为瞬时占用。工程判断是——先按“每块候选数 × 嵌入维度 × 元素字节”估算，再留出编码器激活的余量，块大小取使峰值不超过容量七成的值。具体例子：零样本分类请求把类别名文本嵌入与图像嵌入比对，类别数可达数千，若一次性构造全矩阵，峰值显存会远超单张加速卡可承受范围；改为按类别分块后，峰值被压到与块大小同阶，代价是多次 kernel 启动带来的固定开销，需在块大小与启动次数间取平衡。</p>\n<ul>\n<li>监控项：每请求的候选数分布、块大小实际命中率、显存峰值与容量的比值。</li>\n<li>定位手段：在块循环内埋点记录峰值，区分是编码器激活还是相似度矩阵导致。</li>\n<li>回滚策略：块大小配置随版本走，OOM 触发时回退到上一档更小块大小，而非降精度。</li>\n</ul>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-40\">四十 · 批抖动：负对构成变化引发的损失不稳</h3>\n<p>批抖动指相邻批次之间损失值与排序指标出现非单调波动。根因在负对的构造：sigmoid 损失的非对角元素全部作为负对，批构成一变，负对数量与噪声标签比例随之变化。论文明确讨论了批大小对性能的影响，并指出负对标签由批内构造决定、批构成变化会影响损失稳定性。推理侧虽不计算损失，但同一机制会以“候选集构成变化”的形式重现——同一张图在不同请求里面对的负样本池不同，排序分数不可跨请求直接比较。</p>\n<p>诊断方法是把批内正负比例与相似度矩阵的非对角均值做成时间序列，观察其与请求到达模式的相关性。若抖动与流量突增同步，说明批调度把不同来源的请求混进了同一批，负样本池被污染。代价是调度器需要维护请求来源标签并做亲和性分组，增加了队列管理复杂度与少量排队延迟；收益是排序分数在请求间可比，尾延迟也更可预测。具体例子：一个混合了检索与零样本分类的端点，若两类请求共用同一批，分类请求的类别嵌入会被检索请求的候选图污染成负对，表现为分类置信度随流量波动。</p>\n<div class=\"formula\">$$\\text{jitter}_t=\\left|\\,\\bar{s}^{(\\text{off})}_t-\\bar{s}^{(\\text{off})}_{t-1}\\,\\right|\\Big/\\bar{s}^{(\\text{off})}_{t-1}$$</div>\n<p>该比值持续超过设定带宽即判定批构成失稳，处置是收紧批亲和性分组或回退到按来源隔离的调度配置。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-41\">四十一 · 尾延迟：双塔独立前向的慢侧拖累</h3>\n<p>双塔可独立前向是这套结构在服务侧的核心优势，但也是尾延迟的来源：图像塔与文本塔的耗时不对称，整体请求延迟由慢侧决定。若把两塔放在同一批里同步等待，快侧会被慢侧拖住，P99 被慢侧的长尾拉高。工程做法是把两塔拆成独立队列与独立批，用嵌入缓存解耦——文本嵌入对固定类别集可预计算并缓存，图像嵌入按请求实时计算，二者在排序阶段汇合。</p>\n<p>代价是缓存一致性：类别名文本嵌入一旦更新，缓存必须整体失效，否则排序会用到过期嵌入，形成静默降级。监控应覆盖两塔各自的批等待时间、执行时间与缓存命中率，并把“排序阶段等待慢侧嵌入”的时间单独计量。具体例子：零样本分类端点把类别嵌入预热进缓存后，图像塔成为唯一实时路径，P99 由图像编码器的批等待主导；此时若盲目增大图像批以提高吞吐，单请求延迟反而上升，需要在吞吐与尾延迟之间按 SLO 取点。</p>\n<ul>\n<li>定位手段：按塔拆分延迟直方图，区分排队、执行与汇合三段。</li>\n<li>回滚策略：缓存版本号与模型版本绑定，版本切换时先失效再预热，避免混用。</li>\n<li>容量判断：尾延迟预算应按慢侧 P99 加汇合开销设定，而非按两塔均值。</li>\n</ul>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-42\">四十二 · 静默降级：低精度路径与超参补偿的陷阱</h3>\n<p>最危险的失败模式是不报错的降级。论文未给出 NVFP4/FP8 量化与 Blackwell 部署数据，直接把训练结论套到低精度推理服务上，会低估视觉编码器的精度损失。静默降级的典型链路是：量化后嵌入范数偏移，点积排序轻微翻转，召回率下降几个点但不触发任何告警；运维侧看到的是“服务正常”，业务侧看到的是“结果变差”。防御手段是建立与在线服务并行的影子路径，用高精度配置对小流量请求做对照，持续比对 top-k 重合率。</p>\n<p>代价是影子路径占用额外算力与显存，通常按在线流量的固定比例采样，比例过高会挤占主路径容量。工程判断是——影子采样率应低到不影响主路径 SLO，又高到能在数小时内积累足够对照样本；重合率跌破阈值即自动回滚精度配置。具体例子：把图像塔量化后，若不做影子对照，只能等到业务方反馈才发现检索质量下滑；有了对照路径，重合率的下降会在分钟级暴露，回滚动作可与版本发布系统联动。</p>\n<div class=\"formula\">$$\\text{overlap}_k=\\frac{1}{Q}\\sum_{q=1}^{Q}\\frac{\\left|\\,\\text{top-}k_{\\text{hi}}(q)\\cap\\text{top-}k_{\\text{lo}}(q)\\,\\right|}{k}$$</div>\n<p>该指标同时覆盖排序翻转与嵌入漂移两类问题，是静默降级最直接的哨兵；它不依赖标注数据，只依赖同一请求在两套配置下的输出对照，因此可以在生产流量上持续运行。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-43\">四十三 · 监控分层与回滚决策的工程落点</h3>\n<p>把上述失败模式收拢成一套分层监控：第一层是资源层（显存峰值、块大小命中、两塔队列深度），第二层是数值层（嵌入范数漂移、相似度对角与非对角间隙、top-k 重合率），第三层是业务层（召回率、分类置信度分布、尾延迟分位）。三层指标的采样率与保留窗口不同，资源层全量短窗，数值层采样中窗，业务层全量长窗，避免监控本身成为吞吐瓶颈。回滚决策应由数值层指标自动触发，业务层指标用于事后归因，资源层指标用于容量规划。</p>\n<p>回滚的粒度要按配置项拆分：精度配置、块大小配置、批亲和性配置各自独立版本化，任一指标越界只回退对应项，避免整服务回滚带来的容量抖动。具体机制是给每个配置项打版本号并记录变更时间戳，监控越界时按时间戳定位最近变更并定向回退。代价是配置管理复杂度上升，收益是故障域被切小——一次精度回退不会连带改变批调度，尾延迟不会因回滚而二次恶化。论文的局限正在于未提供量化与部署数据，因此这套分层监控的阈值必须由部署方自行实验标定，不能引用论文中的任何数值作为默认门限。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-44\">四十四 · 批构成漂移与精度塌陷的定位路径</h3>\n<p>sigmoid 损失把负对完全交给批内非对角元素，这既是它摆脱全局归一化的代价，也是它最脆弱的环节。当本地批的构成发生偏移——例如检索服务中单图对多文本的请求占比骤升，或零样本分类请求把类别名文本批量灌入——负对数量与噪声标签比例随之改变，损失曲面与训练时不再一致。诊断上不能只看总损失：应把批内正负对比例、对角相似度均值与非对角相似度分布分开记录，一旦非对角分布向高相似度一侧漂移，就意味着“假负对”在增多，检索排序质量会先于损失数值恶化。定位手段是把相似度矩阵按行做分位数采样落盘，比对线上与离线基线的分布偏移；代价是每次采样都要把 N×N 矩阵的一部分搬出显存，在 N 较大时这笔带宽开销不可忽略，因此只宜按固定间隔抽样而非逐批全量。</p>\n<div class=\"formula\">$$\\rho_{\\text{neg}}=\\frac{\\sum_{i\\neq j}\\mathbb{1}[s_{ij}&gt;\\tau]}{N(N-1)},\\qquad \\text{alarm if } \\rho_{\\text{neg}}\\ \\text{drifts beyond baseline band}$$</div>\n<p>OOM 的根因几乎总是同一个二次方项：矩阵元素数与 N² 成正比，而双塔前向的激活又与 N 线性相关，两者叠加使显存峰值对批大小极为敏感。工程判断是给本地批设硬上限而非自适应放大，并把分片策略与批调度绑定——图像塔与文本塔可独立切分，但相似度矩阵必须在同一分片内闭合计算，否则跨分片归约会重新引入同步。一个具体例子：检索服务把单请求的候选文本数从数十扩到数百时，若仍按请求粒度组批，矩阵规模会随候选数平方膨胀，正确做法是按候选数反推每批可容纳的请求数，把批上限写成候选数的函数而不是固定值。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要怀疑</th><th>定位动作</th></tr></thead><tbody><tr><td>检索 top-k 排序抖动</td><td>批构成偏移、假负对增多</td><td>抽样比对非对角相似度分布</td></tr><tr><td>显存峰值突增后 OOM</td><td>候选数或批上限失控</td><td>按候选数反推批上限并分片</td></tr><tr><td>尾延迟抬升</td><td>大矩阵排序与嵌入搬移</td><td>拆分双塔前向与点积排序阶段</td></tr></tbody></table>\n<p>尾延迟与静默降级往往同源：双塔独立前向让图像与文本两段可以分开部署，但点积排序阶段仍要等两侧嵌入齐备，任何一侧的慢请求都会把整批拖到长尾。更隐蔽的是精度静默降级——论文未给出 NVFP4/FP8 量化与 Blackwell 部署数据，把训练结论直接套到低精度推理上，视觉编码器的嵌入范数分布会先偏移，检索命中率缓慢下滑而不触发任何报错。监控应把嵌入范数均值与 L2 归一化后的余弦分布作为一等指标，与损失、正负比例并列；回滚则以“批上限 + 精度档位”作为联合版本号，任一指标越界即整体退回上一组已验证配置，而不是单独调批大小去掩盖精度问题。</p>\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-45\">四十五 · 口径先于数字：这篇论文能提供什么、不能提供什么</h3>\n<p>把这篇论文放进 Blackwell 推理专卷，第一件事是划清口径边界。论文的实证对象是<strong>训练期的对比目标函数</strong>：在图文检索基准上比较 sigmoid 损失与 softmax 基线，报告“可比或更优”，并讨论批大小、温度、偏置项的消融。它没有给出任何 Blackwell 硬件档位（B200/B300、GB200/GB300 NVL72）上的部署数据，没有 NVFP4/FP8 量化结果，没有 KV cache 占用，也没有分离式预填/解码的 TTFT/TPOT 曲线。因此本部分的任务不是复述论文的检索精度，而是建立一套<strong>读数字的换算口径</strong>：哪些结论可以直接迁移到推理服务，哪些必须重新测。</p>\n<p>可迁移的部分是结构性的：双塔独立前向、损失可分解到本地批、相似度矩阵规模为批大小平方。这三条在推理侧对应三个可直接观测的量——编码器前向延迟、批内排序的显存峰值、以及分片后的跨设备通信量。不可迁移的部分是数值性的：论文的“较小批下可比”是在其训练配置下成立的，换到低精度推理、换到不同的负对构成，结论未必保持。工程判断应当写成：<em>把论文当作批构造与目标函数的依据，把性能数字当作待测项而非既有结论。</em></p>\n<p>具体例子：一个图文检索服务若照搬论文的“小批即可”结论去设定在线批上限，会忽略推理侧真正的瓶颈不在损失归一化，而在相似度矩阵的二次方显存与排序阶段的带宽。前者论文已消除，后者论文只提示存在，未给数值。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-46\">四十六 · 相似度矩阵是唯一贯穿训练与推理的代价项</h3>\n<p>论文的公式给出批内逐对二分类损失：</p>\n<div class=\"formula\">$$\\mathcal{L}=-\\frac{1}{N}\\sum_{i=1}^{N}\\sum_{j=1}^{N}\\left[y_{ij}\\log\\sigma(s_{ij})+(1-y_{ij})\\log(1-\\sigma(s_{ij}))\\right]$$</div>\n<p>其中 $N$ 是本地批大小，$s_{ij}$ 是第 $i$ 张图与第 $j$ 条文本的归一化嵌入点积，$y_{ij}$ 在对角为 1、非对角为 0。这个式子的工程含义不在损失值本身，而在它显式构造了一个 $N\\times N$ 的相似度矩阵。训练时该矩阵参与反向传播；推理时它退化为排序用的打分矩阵，但规模规律不变。</p>\n<p>由此得到本部分唯一可写的容量关系：打分矩阵元素数为 $N^2$，若以 $b$ 字节/元素存储（FP16 为 2，FP8 为 1），单次批内排序的矩阵显存为 $bN^2$。当 $N$ 从 64 增至 256，元素数增长 16 倍；这是部署时设定本地批上限的第一约束，优先于任何编码器侧优化。分片策略的作用是把 $N^2$ 拆到多卡：若按文本维切分到 $k$ 张卡，每卡持有 $N\\times(N/k)$ 的子矩阵，通信量为跨卡拼接的 $N^2/k$ 量级，而非全量。</p>\n<p>推理系统的代价落点：在单图对多文本的检索请求中，图像编码器只前向一次，文本侧批量编码 $M$ 条候选，打分矩阵为 $1\\times M$，此时二次方项不显现；真正的二次方场景是<strong>批内多图多文的互相排序</strong>，例如零样本分类中一批图像对全部类别名文本打分，矩阵为 $B\\times C$，$C$ 为类别数。工程上应把这两类请求分开定容量：检索走线性打分，分类走 $B\\times C$ 的受控矩阵。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-47\">四十七 · 硬件档位与指标：论文未给的，必须自己定义测量口径</h3>\n<p>论文不含 Blackwell 数据，因此本节的表格只列<strong>应当测什么、怎么读</strong>，不填任何虚构数值。读者应把下表当作服务上线前的测量清单，而不是论文结论的转述。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>测量对象</th><th>读法要点</th></tr></thead><tbody>\n<tr><td>TTFT</td><td>图像编码器前向 + 文本编码器前向 + 首次打分</td><td>双塔可并行，TTFT 取两者较大者而非之和；分片后需加跨卡同步</td></tr>\n<tr><td>TPOT / 单请求尾延迟</td><td>排序阶段逐候选打分</td><td>检索场景近似线性于候选数，与批大小平方项无关</td></tr>\n<tr><td>吞吐</td><td>每秒完成的图文对数</td><td>受打分矩阵显存上限约束，而非编码器算力</td></tr>\n<tr><td>显存峰值</td><td>$bN^2$ 打分矩阵 + 双塔激活</td><td>先定 $N$ 上限再谈批调度，顺序不可颠倒</td></tr>\n<tr><td>功耗/能效</td><td>整卡或整机柜</td><td>编码器前向占主导；排序阶段以带宽为主，能效曲线不同于算力密集算子</td></tr>\n</tbody></table>\n<p>硬件档位的选择逻辑：B200/B300 单卡与 GB200/GB300 NVL72 机柜的差别不在打分矩阵的算术，而在<strong>分片后的通信域</strong>。若把 $N^2$ 矩阵按文本维切到多卡，跨卡归约走 NVLink 5 域内与走机柜内 NVLink 的代价不同；NVL72 的价值在于把分片通信压在同一高带宽域内，使 $N$ 的上限可以抬高。这是定性判断，具体带宽收益须实测。</p>\n<p>具体例子：零样本分类服务，类别数 $C=1000$，批内图像 $B=32$，打分矩阵为 $32\\times1000$，FP16 下约 64 KB 量级，显存不是瓶颈；但若把 $B$ 提到 512，矩阵升至 $512\\times1000$，此时瓶颈转移到排序与 top-k 选择的内存访问，而非矩阵存储本身。这说明“批大小平方”在分类形态下被 $C$ 稀释，在互检索形态下才是主导项。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-48\">四十八 · 哪些提升不可比：四类常见的口径错配</h3>\n<p>读这篇论文的数字，最容易犯的错是把训练期的“小批可比”直接换算成推理期的“小批更快”。二者不可比，原因有四：</p>\n<ul>\n<li><strong>目标不同</strong>：训练期小批的收益是减少跨设备归一化同步；推理期小批的代价是编码器利用率下降、批内并行度不足。前者省通信，后者费算力，方向相反。</li>\n<li><strong>负对语义不同</strong>：训练时负对是非对角元素，批构成决定负对数量与噪声比例；推理时不存在负对，打分矩阵只做排序。论文关于负对噪声的消融不能用于推断检索排序质量。</li>\n<li><strong>精度档位不同</strong>：论文未给 NVFP4/FP8 数据。双塔嵌入经 L2 归一化后做点积，低精度下嵌入范数与点积的动态范围会改变排序边界，尤其在小间隔候选之间。任何“可比或更优”的结论在低精度下须重测，不能引用。</li>\n<li><strong>批的构成不同</strong>：论文的批是训练用的图文对批，推理的批是请求聚合批，二者的正负比例、长度分布、图像分辨率分布都不同。批大小相同不代表矩阵语义相同。</li>\n</ul>\n<p>工程上应建立一条换算规则：凡引用论文的批大小结论，必须同时声明该批是训练批还是服务批、精度档位、以及矩阵是 $N\\times N$ 还是 $B\\times C$。三者缺一，数字即不可比。</p>\n<p>具体例子：若某团队把论文“较小批下可比”作为在线服务批上限的依据，把 $N$ 设为 32，则在互检索形态下打分矩阵仅 $32\\times32$，编码器前向成为唯一瓶颈，吞吐被编码器算力锁死；反之若把 $N$ 设为 512 以提吞吐，矩阵升至 $512\\times512$，FP16 下约 0.5 MB 量级虽不致命，但分片通信与排序访存开始主导尾延迟。两种设定都不是论文结论能直接回答的。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-49\">四十九 · 双塔拆分带来的测量口径分裂</h3>\n<p>论文的双塔结构允许图像与文本编码器独立前向，这在推理侧意味着<strong>两个编码器的延迟与吞吐必须分开测</strong>。合并报告一个端到端 TTFT 会掩盖真实瓶颈：图像编码器通常是视觉 Transformer，分辨率与 patch 数决定其算力需求；文本编码器长度由候选文本或类别名决定，通常远短于图像侧。二者在同一批内的利用率不同，合并口径会让容量规划偏向错误的一侧。</p>\n<p>测量口径应写成：图像侧单卡每秒处理图像数、文本侧每秒处理文本数、以及打分阶段的每秒排序对数，三者取最小值作为服务吞吐上限。这一“木桶”关系是双塔拆分的直接后果，也是论文结构在推理侧最实用的推论。分片时，图像与文本可分别切分到不同卡组，跨组只交换归一化嵌入，通信量为 $N\\times d$（$d$ 为嵌入维度），远小于 $N^2$ 矩阵，因此双塔拆分本身是降低通信的杠杆。</p>\n<p>代价落在显存与调度：两套编码器的激活峰值不同，若共用同一批调度器，批上限须取两者较小者，否则一侧 OOM。工程判断是给图像与文本分别设批上限，再在打分阶段做受控拼接，而不是用一个全局批大小统一约束。</p>\n<p>具体例子：一个零样本分类请求含 1 张图与 1000 条类别名文本，图像侧批为 1、文本侧批为 1000，两侧批大小相差三个数量级。若强行统一批大小，要么图像侧空转，要么文本侧被截断，两种都是口径错配。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-50\">五十 · 把论文结论落成可执行的容量判断</h3>\n<p>综合以上，本部分给出的工程判断是三条可执行规则，而非对论文数字的转述。第一条：<strong>先定打分矩阵形态再定批上限</strong>——互检索形态按 $bN^2$ 约束，分类形态按 $B\\times C$ 约束，两者不可混用同一批大小。第二条：<strong>双塔延迟分开测、吞吐取最小值</strong>——合并口径会掩盖图像侧的算力瓶颈或文本侧的批截断。第三条：<strong>论文的“可比或更优”只在训练口径内成立</strong>——迁移到 NVFP4/FP8 推理服务前，必须重测嵌入点积的排序边界，尤其是小间隔候选，因为 L2 归一化后的低精度点积会改变排序稳定性，而论文未提供该档位数据。</p>\n<p>最后落在具体机制上：sigmoid 损失消除的是跨样本归一化同步，它把训练期的通信代价从全局归约降为本地批内计算；但推理期的通信代价并未随之消失，只是转移到了双塔分片与打分矩阵拼接上。因此读这篇论文的正确姿势是——把它当作<strong>批构造与目标函数的依据</strong>，把每一个性能数字标注为“训练口径、未量化、未上 Blackwell”，再在自有硬件档位上按上表重测。任何跳过重测直接引用的吞吐或延迟提升，都属于口径错配，不可比。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-51\">五十一 · 口径边界：sigmoid 双塔在推理侧的不可比项与容量红线</h3>\n<p>把这篇论文的数字搬进 Blackwell 推理容量表之前，先要认清它的口径只覆盖训练侧的批构造与检索精度，不含任何部署档位信息。论文报告 sigmoid 损失在图文检索基准上与 softmax 基线可比或更优，但数据集、指标数值与批大小均未给出，因此任何“提升百分之几”的转述都不可信。可比的前提是同一编码器、同一嵌入维度、同一检索协议；一旦换成 NVFP4/FP8 量化后的视觉塔，精度损失未被论文测量，训练结论不能外推为低精度服务指标。TTFT、TPOT、吞吐、显存峰值与功耗这五项在本方案中没有实测口径，只能由相似度矩阵的二次方规模与双塔独立前向结构定性推导。</p>\n<p>推理时的核心代价不在注意力，而在打分矩阵。设候选文本数为 $M$、图像批为 $B$、嵌入维度 $d$，打分与排序的显存与算力近似为：</p>\n<div class=\"formula\">$$C_{\\text{score}} \\approx \\mathcal{O}(B \\cdot M \\cdot d),\\quad S_{\\text{logits}} \\approx \\mathcal{O}(B \\cdot M)$$</div>\n<p>训练侧 $B=M=N$ 时退化为批大小平方，这正是论文局限所指；服务侧则要把 $M$ 与 $B$ 解耦——单图对多文本的检索请求是 $B{=}1$、$M$ 很大的排序形态，零样本分类则是 $M$ 等于类别数的固定打分。此时平方项被拆成线性项，但 $M$ 增大仍线性推高打分核的显存与带宽占用，需分片或分块点积控制峰值。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>论文覆盖</th><th>推理部署需另测</th></tr></thead><tbody><tr><td>批大小</td><td>训练全局批与本地批关系</td><td>服务侧并发批与本地批上限</td></tr><tr><td>精度</td><td>未涉及量化</td><td>视觉塔 NVFP4/FP8 精度损失</td></tr><tr><td>延迟指标</td><td>无 TTFT/TPOT</td><td>双塔前向拆分后的端到端时延</td></tr><tr><td>显存</td><td>平方矩阵定性</td><td>打分核峰值与分片策略</td></tr></tbody></table>\n<p>失效条件集中在两处。其一是盲目放大本地批：负对数量随批增大而增多，批构成偏差会引入噪声标签，训练侧表现为损失不稳，服务侧则表现为打分矩阵 OOM，必须用本地批上限与分片兜底。其二是把训练超参直接迁移：温度与偏置项对 sigmoid 损失性能有影响且论文仅做定性消融，部署时应作为独立超参重调，不能沿用训练值。工程判断是：双塔可独立前向，适合把图像塔与文本塔拆到不同并行域做低延迟检索服务，但容量规划必须以打分矩阵的 $B \\cdot M$ 规模为红线，而非以编码器 FLOPs 估算。</p>\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-52\">五十二 · 从训练目标迁到推理服务：可迁移的是分解性，不是损失本身</h3>\n<p>把这篇论文的方案搬到推理侧，首先要分清两件事：sigmoid 损失是训练期的目标函数，推理期并不存在损失计算。真正可迁移的是它背后的结构性质——图文相似度不再需要跨样本归一化，因此每个查询与其候选集合的比对可以独立成块。这意味着检索服务可以把“单图对多文本”或“单文本对多图”的请求切成互不依赖的相似度块，块内做点积排序，块间只做归并，不需要任何全局 logits 同步。迁到 Blackwell 上，这正好对应双塔独立前向加一个轻量排序核的形态：图像编码器与文本编码器分别批调度，嵌入写入显存后由一个小算子完成矩阵乘与 top-k。</p>\n<p>代价落在相似度矩阵的二次方增长上。设候选集大小为 <span>M</span>、查询批为 <span>B</span>、嵌入维度为 <span>d</span>，一次比对的计算量为</p>\n<div class=\"formula\">$$C = 2 \\cdot B \\cdot M \\cdot d,\\qquad S_{\\text{mem}} \\approx 4 \\cdot B \\cdot M \\ \\text{(FP32 logits)}$$</div>\n<p>在 FP8 或 NVFP4 下嵌入本身占用不大，但若把 logits 物化成矩阵再排序，<span>B·M</span> 这一项会迅速吃掉显存带宽。工程判断是：不要物化完整相似度矩阵，用分块 GEMM 加流式 top-k，把 <span>M</span> 切成能塞进 TMEM 或共享内存的瓦片。举例：一个以图搜文的请求带 512 个候选文本、批 32，若 <span>d</span>=768，朴素物化 logits 就是 32×512 的 FP32 矩阵，单请求量不大，但连续批处理下并发请求数一多，这块临时缓冲会成为显存峰值的隐形来源，必须在调度层设上限。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-53\">五十三 · 迁到非双塔架构：交叉编码器与生成式多模态要重做</h3>\n<p>这套分解性依赖双塔：图像与文本各自独立编码，相似度只是两个已归一化向量的点积。迁到交叉编码器（cross-encoder）就失效——图文在早期层就交互，无法把候选文本预编码成可缓存的嵌入，每次查询都要对每个候选跑一次完整前向，计算量从 <span>B·M·d</span> 变成 <span>B·M·</span>整网前向。此时 sigmoid 目标的“逐对独立”反而变成负担：独立判定意味着没有跨候选的归一化来校准分数尺度，排序质量依赖分数本身的可比性，而交叉编码器的输出分数在不同候选间未必同尺度。工程上要么退回 softmax 式的候选集内归一化，要么引入校准层，两者都抵消了原方案省通信的好处。</p>\n<p>迁到生成式多模态模型（图像进、文本出）同样不适用：那里没有“批内图文对”的概念，视觉 token 进入解码器的 KV cache，检索退化为前缀匹配或嵌入检索的混合形态。sigmoid 损失能提供的是一个可缓存的图像嵌入塔，用于粗召回；精排仍要靠生成模型或交叉编码器。判断是：把该方案定位在“召回层”的嵌入服务，而不是端到端排序方案。代价体现在两段式管线的延迟叠加——嵌入塔前向加 ANN 检索构成召回延迟，精排再叠加一次前向，SLO 要按两段分别定预算，不能把召回的低延迟当成整体延迟。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-54\">五十四 · 迁到低精度与 Blackwell 数值栈：没有现成数据，必须自己标定</h3>\n<p>论文未给出 NVFP4/FP8 量化、KV cache 与 Blackwell 档位的部署数据，这是迁移时最硬的一条边界。双塔嵌入经 L2 归一化后取值范围受限，看起来对量化友好，但点积排序对嵌入的微小扰动敏感：两个候选的分数差可能远小于量化步长，低精度下排序会翻转。设嵌入量化误差为 <span>ε</span>，两候选真实分数差为 <span>Δ</span>，当 <span>ε·d</span> 量级接近 <span>Δ</span> 时 top-1 就不再稳定。工程做法是分层量化：图像塔与文本塔的激活用 FP8，嵌入存储用 FP8 并在比对前做一次高精度重缩放，或者对 top-k 候选做 FP16 重打分。tcgen05 的 MMA 适合做分块点积，但重打分阶段要单独留一个高精度核。</p>\n<p>具体例子：零样本分类把类别名文本嵌入与图像嵌入比对取最大，类别数 <span>K</span> 就是候选集 <span>M</span>。若 <span>K</span> 很大（细粒度分类），类别嵌入可离线预编码并常驻显存，查询侧只做一次图像前向加一次 <span>K</span> 维点积。此时量化误差影响的是 <span>K</span> 个分数间的相对次序，而非绝对精度，用 FP8 存类别嵌入、FP16 做最终比对是可行的折中。代价是显存：<span>K·d</span> 的嵌入表在 FP8 下减半，但若 <span>K</span> 到十万级、<span>d</span>=768，这张表本身就要按分片切到多卡，跨卡归并 top-k 又引入通信，与“省通信”的初衷相抵。规模上限就在这里：候选集大到需要跨卡分片时，分解性带来的通信节省被归并通信吃掉。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-55\">五十五 · 批构成与负对噪声：推理侧没有负对，但有候选集偏差</h3>\n<p>训练期负对由批内非对角元素构成，批构成变化影响负对数量与噪声标签比例。推理期没有负对标签，但同构的问题以“候选集偏差”的形式出现：检索服务的候选池由业务决定，若候选池里同类样本密集，点积分数的区分度下降，排序靠前的候选可能只是嵌入空间里彼此靠近的一簇。sigmoid 目标训练出的嵌入没有经过候选集内归一化，分数是逐对独立的绝对匹配度，这在小候选集上稳定，在大候选集上会暴露长尾——大量候选的分数挤在相近区间，top-k 边界处的排序对量化误差和嵌入范数分布极其敏感。</p>\n<p>监控指标要相应调整：除检索排序延迟与显存峰值外，应监控候选集内分数分布的熵与 top-k 边界间隔（第 k 名与第 k+1 名的分数差）。边界间隔持续变小是候选池膨胀或嵌入退化的信号。工程判断是给 top-k 归并设一个间隔阈值，间隔低于阈值时触发高精度重打分，把低精度快路径与高精度慢路径做成两级。代价是尾延迟：重打分请求的比例决定 P99，容量规划要按重打分比例留出算力余量，而不是按平均路径算。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-56\">五十六 · 规模上限与不适用清单</h3>\n<p>给出判断而非口号。这套方案适用的边界有三条：其一，双塔可独立前向，候选侧嵌入可离线预编码并缓存；其二，候选集规模在单卡或单机可归并的范围内，跨卡分片的归并通信不超过它省下的全局同步；其三，精度要求允许嵌入走低精度、排序走两级。超出任一条，收益递减。</p>\n<ul>\n<li>不适用：交叉编码器精排、生成式多模态端到端排序、需要跨候选归一化校准分数的场景。</li>\n<li>不适用：候选集动态变化且无法预编码的在线场景——每次查询都要重编码候选，双塔的缓存优势消失。</li>\n<li>慎用：极大规模零样本分类，类别嵌入表跨卡分片后归并通信成为瓶颈。</li>\n<li>慎用：对排序稳定性要求极高的场景，低精度点积的 top-k 翻转需要额外重打分兜底。</li>\n</ul>\n<table class=\"mini\"><thead><tr><th>迁移方向</th><th>要改的部分</th><th>主要代价</th></tr></thead><tbody><tr><td>双塔检索服务</td><td>分块 GEMM 加流式 top-k，不物化 logits</td><td>显存峰值、归并通信</td></tr><tr><td>交叉编码器精排</td><td>恢复候选集内归一化或加校准层</td><td>每候选整网前向，延迟线性增长</td></tr><tr><td>零样本分类</td><td>类别嵌入离线预编码、分层量化</td><td>嵌入表显存、跨卡归并</td></tr><tr><td>生成式多模态</td><td>仅用作召回层嵌入塔</td><td>两段式管线延迟叠加</td></tr></tbody></table>\n<p>规模上限的定量抓手是归并通信与本地比对的比值。设单卡本地比对耗时为 <span>\\(T_{\\text{local}}\\)</span>、跨卡归并耗时为 <span>\\(T_{\\text{merge}}\\)</span>，当 <span>\\(T_{\\text{merge}}\\)</span> 超过 <span>\\(T_{\\text{local}}\\)</span> 的一个可观比例时，继续扩候选集不如加本地批。这个比值要在目标硬件上用实际分片策略测，不能从论文的训练结论外推——论文只报了检索基准上可比或更优，没有给部署延迟与吞吐数据。最后落在具体机制上：把 top-k 归并做成可配置的分片粒度，按 <span>B·M</span> 与单卡显存上限反推每卡候选瓦片大小，让归并通信与本地比对在同一量级，这是迁移到 Blackwell 多卡检索服务时唯一需要先标定的参数。</p>\n\n<h3 id=\"paper-sigmoid-loss-for-language-image-pre-2023-sec-57\">五十七 · 迁移边界：sigmoid 双塔方案在哪些系统上会失效</h3>\n<p>这套方案的迁移前提是「相似度矩阵只在本批内闭合」。一旦目标系统的请求形态破坏这个闭合性，sigmoid 损失的工程优势立刻退化为代价。典型失效场景是跨请求的全局排序：图文检索服务若要求把当前请求的文本嵌入与一个持续增长的候选库做全量比对，候选库规模 M 远大于本地批 B，则单次请求的比对代价为 O(B·M·d)，而非训练时的 O(B²)。此时 sigmoid 逐对独立的性质不再带来通信节省——因为瓶颈已从「跨设备 logits 归一化」转移到「候选嵌入的带宽读取与排序」。设嵌入维度 d、批 B、候选数 M，单卡比对所需的显存驻留量为 <span class=\"formula\">$$S_{\\text{rank}} = (B + M)\\cdot d \\cdot b_{\\text{elem}}$$</span>，其中 b_elem 为元素字节数。在 FP8 下 b_elem=1，但若视觉编码器输出仍需 BF16 保精度，则实际按 2 字节计。工程判断：候选库超过单卡显存容量时必须引入分片+两阶段重排，sigmoid 训练侧的「本地批闭合」结论不能直接平移为服务侧的「无全局同步」。</p>\n<p>第二个边界是负对语义的迁移。sigmoid 损失把批内非对角元素一律标为负，这在图文预训练中成立，因为同批不同对的图文确实不匹配。但迁到细粒度领域——例如同一商品的多个视角图配同一段描述、或同一文档的多张配图——批内会出现「伪负对」：标签为 0 但语义上部分匹配。此时损失梯度被系统性污染，检索排序在语义近邻上出现塌缩。判断准则不是调温度，而是先做批构成审计：统计批内语义重复率 ρ，若 ρ 超过阈值则必须改用去重采样或引入软标签，否则 sigmoid 的逐对独立性反而放大噪声。论文只给出批大小、温度与偏置项的消融方向，未给出 ρ 的量化边界，部署侧需自行以离线检索召回率作为验收指标。</p>\n<p>第三个边界是精度迁移。论文未提供 NVFP4/FP8 量化与 Blackwell 档位的部署数据，因此把训练结论直接套到低精度推理服务存在系统性风险。双塔结构中视觉编码器的激活分布比文本侧更宽，FP8 下 L2 归一化前的投影输出容易溢出；而 sigmoid 推理只需点积排序，误差会被 top-k 排序放大——一个 1e-2 量级的嵌入扰动足以翻转近邻名次。工程上应把量化评估拆成两段：先测嵌入余弦相似度的分布偏移，再测 top-1/top-5 召回跌落，二者不可互相替代。若视觉塔必须保 BF16 而文本塔可下探 FP8，则分离式部署的收益主要落在文本侧带宽，而非算力。</p>\n<table class=\"mini\"><thead><tr><th>迁移目标</th><th>需改动</th><th>主要代价</th><th>判断</th></tr></thead><tbody><tr><td>大规模候选库检索</td><td>候选分片+两阶段重排</td><td>带宽与显存驻留</td><td>闭合性失效，需重设计</td></tr><tr><td>细粒度多视角领域</td><td>批去重或软标签</td><td>负对噪声、收敛稳定性</td><td>先审计批构成再迁移</td></tr><tr><td>低精度推理服务</td><td>分段量化验收</td><td>排序翻转、精度跌落</td><td>无数据，须独立实验</td></tr></tbody></table>\n<p>规模上限落在相似度矩阵的二次方项上：本地批 B 翻倍，矩阵显存与计算均四倍增长，而检索收益通常只呈亚线性。因此在 Blackwell 这类高带宽平台上，正确的扩容方向不是增大单批 B，而是把 B 固定在显存峰值的安全区内，用更多并发流与分片并行换取吞吐；sigmoid 损失的可分解性恰好支持这种「小批多流」的调度，但前提是服务侧排序逻辑不要求跨流全局归一化。一旦业务要求全局 top-k，二次方开销就从训练侧转移到服务侧的归并阶段，此时应显式评估归并通信量是否已抵消掉 sigmoid 带来的同步节省——这是迁移决策的分水岭，而非口号式的「更省通信」。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Sigmoid Loss for Language </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Image Pre-Tra…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2023 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Sigmoid Loss for Langua… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>softmax 对比损失基线</td></tr><tr><td>主要结果</td><td>论文报告 sigmoid 损失在图文检索任务上与 softmax 基线可比…</td></tr><tr><td>消融</td><td>论文讨论了批大小、温度参数与偏置项对 sigmoid 损失性能的影响，并比…</td></tr><tr><td>局限</td><td>相似度矩阵随批大小平方增长，显存与计算开销上升；负对数量随批增大而增多，可…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-sigmoid-loss-for-language-image-pre-2023 · 共 9 个片段</p>\n";break;}}})();
